-- ------------------------------------------------------------ dnd_w3.lua
do
--[[ =========================================================================
  dnd_w3.lua — the only file in the engine that talks to WC3.

  Everything above this layer is pure Lua, which is what makes the whole
  combat system testable: tools/harness.py swaps in mock natives with the same
  names and a full fight runs headless.

  Natives chosen here are deliberately limited to the ones verified present in
  common.j for 1.31+ (see tools/check.py --natives). Anything optional goes
  through w3.safe() so a missing native logs once and degrades instead of
  taking the map down.
========================================================================== ]]
DND = DND or {}
DND.w3 = {}
local w3 = DND.w3
local C = DND.CONST

w3.verbose = false
local missing = {}

--- Call a native if the host provides it; otherwise warn once and return nil.
function w3.safe(name, ...)
  local f = _G[name]
  if type(f) ~= "function" then
    if not missing[name] then
      missing[name] = true
      w3.log("!! native missing: " .. name .. " (feature disabled)")
    end
    return nil
  end
  return f(...)
end

function w3.has(name) return type(_G[name]) == "function" end

---------------------------------------------------------------------- ids
local handleIds = {}
local nextId = 1
function w3.id(handle)
  if handle == nil then return 0 end
  local cached = handleIds[handle]
  if cached then return cached end
  local i
  if w3.has("GetHandleId") then i = GetHandleId(handle) else
    nextId = nextId + 1; i = nextId
  end
  handleIds[handle] = i
  return i
end
function w3.resetIds() nextId = 1 handleIds = {} end

--- Four-char code from a string, for the rare places we need one at runtime.
function w3.cc(s)
  local n = 0
  for i = 1, #s do n = n * 256 + string.byte(s, i) end
  return n
end

---------------------------------------------------------------------- geometry
function w3.x(u) return GetUnitX(u) end
function w3.y(u) return GetUnitY(u) end
function w3.dist(u1, u2)
  local dx, dy = GetUnitX(u1) - GetUnitX(u2), GetUnitY(u1) - GetUnitY(u2)
  return SquareRoot(dx * dx + dy * dy)
end
function w3.distPts(x1, y1, x2, y2)
  local dx, dy = x1 - x2, y1 - y2
  return SquareRoot(dx * dx + dy * dy)
end
--- Snap to the 5 ft grid so battles read like a printed battle map.
function w3.snap(x, y)
  local g = C.FIVE_FEET
  return C.round(x / g) * g, C.round(y / g) * g
end
function w3.moveTo(u, x, y, faceTarget)
  if DND.config and DND.config.gridSnap then x, y = w3.snap(x, y) end
  SetUnitX(u, x); SetUnitY(u, y)
  if faceTarget then
    SetUnitFacing(u, w3.angleTo(x, y, GetUnitX(faceTarget), GetUnitY(faceTarget)))
  end
end

--- BJ has no angle helper with this name; compute it from the vector instead.
function w3.angleTo(x1, y1, x2, y2)
  local rad = math.atan2(y2 - y1, x2 - x1)
  return rad * 180 / math.pi
end

---------------------------------------------------------------------- freeze
-- The heart of "turn based": a paused unit accepts no order, takes no path,
-- and attacks nothing. Everyone sleeps until the initiative says otherwise.
function w3.freeze(u)
  if not u then return end
  PauseUnit(u, true)
  SetUnitPathing(u, false)
  -- kill WC3's own damage even if something unpauses it (see README §Why)
  BlzSetUnitWeaponBooleanField(u, UNIT_WEAPON_BF_ATTACKS_ENABLED, 0, false)
  BlzSetUnitWeaponBooleanField(u, UNIT_WEAPON_BF_ATTACKS_ENABLED, 1, false)
end

function w3.unfreeze(u, allowAttacks)
  if not u then return end
  PauseUnit(u, false)
  SetUnitPathing(u, true)
  BlzSetUnitWeaponBooleanField(u, UNIT_WEAPON_BF_ATTACKS_ENABLED, 0, not not allowAttacks)
  BlzSetUnitWeaponBooleanField(u, UNIT_WEAPON_BF_ATTACKS_ENABLED, 1, not not allowAttacks)
end

--- Stop WC3's real-time attack engine for a unit; we deal all damage in Lua.
function w3.disableRealDamage(u, off)
  local v = not off
  BlzSetUnitWeaponBooleanField(u, UNIT_WEAPON_BF_ATTACKS_ENABLED, 0, v)
  BlzSetUnitWeaponBooleanField(u, UNIT_WEAPON_BF_ATTACKS_ENABLED, 1, v)
end

---------------------------------------------------------------------- life
function w3.hp(u)      return GetUnitState(u, UNIT_STATE_LIFE) end
function w3.maxHp(u)   return BlzGetUnitMaxHP(u) end
function w3.setHp(u, v) SetUnitState(u, UNIT_STATE_LIFE, C.clamp(v, 0, w3.maxHp(u))) end
function w3.alive(u)   return u ~= nil and GetUnitState(u, UNIT_STATE_LIFE) > -0.5 end

---------------------------------------------------------------------- log
function w3.log(msg)
  if DND.testMode then
    table.insert(DND.logLines, msg)
    if DND.testVerbose then print("[wc3] " .. msg) end
    return
  end
  BJDebugMsg(msg)
end

--- Floating numbers above a unit: the entire reason this feels like D&D.
function w3.textTag(u, text, size, r, g, b, rise)
  if DND.testMode then return nil end
  local t = CreateTextTag()
  SetTextTagText(t, text, size * 1.0e-4)
  SetTextTagPosUnit(t, u, 24)
  SetTextTagVelocity(t, 0, (rise or 18))
  SetTextTagLifespan(t, 1.6)
  SetTextTagFadepoint(t, 1.1)
  SetTextTagColor(t, r or 255, g or 255, b or 255, 255)
  w3.after(2.2, function() if t then DestroyTextTag(t) end end)
  return t
end

---------------------------------------------------------------------- fx
function w3.fxTarget(path, u, attach)
  if DND.testMode or type(path) ~= "string" or path == "" then return nil end
  local e = AddSpecialEffectTarget(path, u, attach or "origin")
  if e then w3.after(2.0, function() DestroyEffect(e) end) end
  return e
end

function w3.playAnim(u, name)
  if w3.has("SetUnitAnimation") then SetUnitAnimation(u, name or "stand") end
end

---------------------------------------------------------------------- timing
w3.timers = {}
local function newTimer(delay, fn)
  if DND.testMode then
    -- immediate execution keeps the state machine synchronous under test
    fn()
    return nil
  end
  local t = CreateTimer()
  table.insert(w3.timers, { t = t, fn = fn })
  TimerStart(t, delay, false, function()
    for i, e in ipairs(w3.timers) do
      if e.t == t then table.remove(w3.timers, i) break end
    end
    DestroyTimer(t)
    fn()
  end)
  return t
end
--- Defer by `delay` seconds. In the headless harness these fire at once so a
--- whole encounter resolves without wall-clock waiting.
function w3.after(delay, fn) return newTimer(delay, fn) end
function w3.cancelAll()
  for _, e in ipairs(w3.timers) do if e.t then DestroyTimer(e.t) end end
  w3.timers = {}
end

---------------------------------------------------------------------- camera
function w3.lookAt(u, quick)
  if DND.testMode then return end
  local x, y = GetUnitX(u), GetUnitY(u)
  w3.safe("SetCameraField", CAMERA_FIELD_TARGET_DISTANCE, 1180, 0)
  w3.safe("SetCameraField", CAMERA_FIELD_ANGLE_OF_ATTACK, 62, 0)
  PanCameraToTimed(x, y, quick and 0.35 or 0)
end

---------------------------------------------------------------------- misc
function w3.rand(a, b) return GetRandomInt(a, b) end
function w3.name(u) return GetUnitName(u) or "?" end
function w3.typeId(u) return GetUnitTypeId(u) end

return w3

end

-- ------------------------------------------------------------ dnd_dice.lua
do
--[[ =========================================================================
  dnd_dice.lua — the RNG and every roll the game makes.

  One rule drives this file: NEVER call math.random(). In WC3 the Lua state is
  shared with the game's own seeded RNG, and in any multiplayer-capable build a
  client-local RNG desyncs instantly. We roll through GetRandomInt, and the
  test harness replaces that one function with a seeded stream so fights are
  byte-for-byte reproducible.
========================================================================== ]]
DND = DND or {}
DND.Dice = {}
local Dice = DND.Dice
local C = DND.CONST

Dice.debug = false          -- print every die face to the log
local stream = {}           -- deterministic queue used by the test harness
local streamIdx = 1

--- Script the RNG for a test. Values are consumed in order; once they run out
--- the LAST value repeats forever. That is the convention that makes a test
--- readable: script({20}) means "this attack is a critical", whatever number of
--- damage dice the rules path happens to roll afterwards, so the assertion does
--- not have to model the engine's internal roll count. Pass {} to hand control
--- back to the engine RNG (used by the soak tests).
function Dice.script(values)
  stream = {}
  for i = 1, #(values or {}) do stream[i] = values[i] end
  streamIdx = 1
end

function Dice.isScripted() return streamIdx <= #stream end

--- Core roll: inclusive integer range.
function Dice.roll(low, high)
  low, high = math.floor(low), math.floor(high)
  if high < low then low, high = high, low end
  if low == high then return low end
  if #stream > 0 then
    local v = stream[math.min(streamIdx, #stream)]
    streamIdx = streamIdx + 1
    return math.floor(C.clamp(v, low, high))
  end
  return GetRandomInt(low, high)
end

local function dieFace(sides, forceMax)
  if forceMax then return sides end
  return Dice.roll(1, sides)
end

--- Roll a parsed template.
---   opts.max   -> every die shows its maximum face (Sneak Attack style)
---   opts.double-> roll every die twice (the 5e crit rule)
---   opts.bonus -> flat addition on top of the template's own modifier
---   opts.min   -> floor, used so damage can never drop below 1
function Dice.rollTemplate(t, opts)
  opts = opts or {}
  local copies = opts.double and 2 or 1
  local forceMax = opts.max or t.max
  local faces, total = {}, 0
  for _, d in ipairs(t.dice) do
    for _ = 1, copies do
      local f = dieFace(d.d, forceMax)
      faces[#faces + 1] = f
      total = total + f
    end
  end
  total = total + (t.mod or 0) + (opts.bonus or 0)
  if opts.min and total < opts.min then total = opts.min end
  return { total = total, faces = faces, label = C.diceLabel(t),
           mod = (t.mod or 0) + (opts.bonus or 0), count = #faces }
end

--- "2d6+1d4+3" in one call.
function Dice.rollExpr(expr, opts)
  local t = C.parseDice(expr)
  if not t then
    DND.logError("bad dice expression: " .. tostring(expr))
    return { total = 0, faces = {}, label = "0", mod = 0, count = 0 }
  end
  return Dice.rollTemplate(t, opts)
end

---------------------------------------------------------------------- d20 core
--- The only place a d20 is touched. Returns a rich result object so every
--- caller (log, text tag, concentration check) can replay the maths.
---   adv  :  1 advantage, -1 disadvantage, 0 neither
function Dice.d20(mod, adv, opts)
  opts = opts or {}
  local a = Dice.roll(1, 20)
  local b = nil
  if adv == 1 or adv == -1 then b = Dice.roll(1, 20) end

  local chosen, rolled
  if not b then
    rolled, chosen = a, a
  elseif adv == 1 then
    rolled, chosen = (a >= b) and a or b, (a >= b) and a or b
  else
    rolled, chosen = (a <= b) and a or b, (a <= b) and a or b
  end

  local nat = rolled                    -- "natural" 20 / 1 ignores all maths
  local total = nat + (mod or 0)
  local r = {
    natural = nat, total = total, mod = mod or 0,
    dice = { a, b }, adv = adv or 0,
    crit = (opts.autoCrit or nat == 20) and true or false,
    fumble = (nat == 1) and true or false,
  }
  r.critOnly = (nat == 20) and true or false
  if opts.dc then
    r.dc = opts.dc
    r.success = (nat == 20) or (nat ~= 1 and total >= opts.dc)
    if opts.autoFail and opts.autoFail[1] then r.success = false end
  end
  r.text = string.format("d20%s %s %s = %d",
    (adv == 1 and " (adv)") or (adv == -1 and " (dis)") or "",
    nat, C.signed(mod or 0), total)
  return r
end

---------------------------------------------------------------------- checks
--- Ability check or saving throw. `score` optional; pass `mod` directly.
function Dice.check(mod, opts)
  opts = opts or {}
  local adv = opts.adv or 0
  if opts.disadv then adv = -1 end
  local r = Dice.d20(mod, adv, { dc = opts.dc, autoCrit = opts.autoCrit,
                                 autoFail = opts.autoFail })
  if opts.autoSuccess then r.success = true end
  r.label = opts.name or "check"
  return r
end

--- Attack roll vs an AC. Returns { hit, crit, total, natural, ... }
function Dice.attackRoll(bonus, ac, opts)
  opts = opts or {}
  local r = Dice.d20(bonus, opts.adv or (opts.disadv and -1 or 0),
                      { autoCrit = opts.autoCrit, dc = ac })
  r.ac = ac
  r.crit = opts.autoCrit or r.natural == 20
  r.hit = r.crit or (r.natural ~= 1 and r.total >= ac)
  return r
end

--- Initiative. Tie-break by DEX mod, then a coin flip, then a stable index.
function Dice.initiative(dexMod, tiebreak, coin)
  local d = Dice.d20(dexMod or 0, 0)
  return { score = d.total, natural = d.natural, dex = dexMod or 0,
           tie = tiebreak or 0, coin = coin or Dice.roll(1, 100) }
end

--- Percentile roll (loot, wild magic, mishaps).
function Dice.percent() return Dice.roll(1, 100) end

--- Convenience: roll N dice of X, no modifier.
function Dice.pool(n, sides)
  local t = { dice = {}, mod = 0 }
  for _ = 1, n do t.dice[#t.dice + 1] = { d = sides } end
  return Dice.rollTemplate(t)
end

return Dice

end

-- ------------------------------------------------------------ dnd_combatant.lua
do
--[[ =========================================================================
  dnd_combatant.lua — the D&D creature, and how it is mirrored into WC3.

  A combatant is a Lua table (the truth) wrapped around a WC3 unit (the body).
  Everything the engine needs is on the Lua side; the unit object is used for
  model, position, HP bar, and the ability buttons. Synced one way:
  Lua -> WC3, via Combatant.sync().
========================================================================== ]]
DND = DND or {}
DND.Combatant = {}
local Combatant = DND.Combatant
local C = DND.CONST
local w3 = DND.w3

local byHandle = {}          -- handleId -> combatant
local all = {}               -- ordered list
local nextCid = 1

local ABILITY_KEYS = { "str", "dex", "con", "int", "wis", "cha" }

---------------------------------------------------------------------- lookup
function Combatant.get(u)
  if not u then return nil end
  return byHandle[w3.id(u)]
end
function Combatant.byId(cid) return all[cid] end
function Combatant.all() return all end
function Combatant.count() return #all end

function Combatant.listOnSide(side)
  local out = {}
  for _, cbt in ipairs(all) do
    if cbt.side == side and not cbt.removed then out[#out + 1] = cbt end
  end
  return out
end

--- Living creatures on one side, exactly one side. `Combatant.living(nil)` means
--- "everybody", which is right for end-of-fight checks and wrong for reading a
--- threat list; keep the two intentions in different functions.
function Combatant.livingOf(side)
  local out = {}
  for _, cbt in ipairs(all) do
    if cbt.side == side and cbt.hp > 0 and not cbt.removed then out[#out + 1] = cbt end
  end
  return out
end

function Combatant.living(side)
  local out = {}
  for _, cbt in ipairs(all) do
    if (side == nil or cbt.side == side) and cbt.hp > 0 and not cbt.removed then
      out[#out + 1] = cbt
    end
  end
  return out
end

function Combatant.remove(cbt)
  cbt.removed = true
  byHandle[cbt.hid] = nil
end

--- Drop every marked combatant out of the ordered list. `remove` unregisters the
--- unit handle, which is what the rules check, but `all` is what anything that
--- walks the whole roster reads — so a session of repeated encounters would keep
--- growing it forever. Cheap, and the delve calls it between rooms.
function Combatant.compact()
  local keep = {}
  for _, cbt in ipairs(all) do
    if not cbt.removed then keep[#keep + 1] = cbt end
  end
  for i = #all, 1, -1 do all[i] = nil end
  for i, cbt in ipairs(keep) do all[i] = cbt end
  return #all
end

---------------------------------------------------------------------- build
--- spec: a 5e-ish statblock. Fields all have sane defaults so a monster can be
--- declared in four lines: { name="Goblin", ac=15, hp=7, speed=30, str=8, dex=14 }
function Combatant.new(spec, unit)
  assert(spec, "Combatant.new needs a spec")
  local level = spec.level or 1
  local prof = spec.prof or C.proficiency(level)
  local scores = {}
  for _, k in ipairs(ABILITY_KEYS) do scores[k] = spec[k] or 10 end
  local mods = {}
  for _, k in ipairs(ABILITY_KEYS) do mods[k] = C.abilityMod(scores[k]) end

  local cbt = {
    cid = nextCid, name = spec.name or "Creature", unit = unit,
    hid = unit and w3.id(unit) or 0,
    side = spec.side or C.SIDE.PARTY,
    level = level, prof = prof,
    scores = scores, mods = mods,
    ac = spec.ac or (10 + mods.dex),
    -- Extra Attack, from a level-up or from the statblock (a beast that has two
    -- natural weapons writes `extraAttack = 2` and gets the same loop for free).
    extraAttack = spec.extraAttack,
    armor = spec.armor,                -- "none" matters: the level ladder's +1
                                       -- is armour getting better, not magic
    spellAbility = spec.spellAbility,  -- which score a save DC is built from
    hpMax = spec.hp or (level * 5 + (mods.con or 0) * level),
    speed = spec.speed or 30,          -- feet per turn
    initiative = spec.initiative or mods.dex,
    senses = spec.senses or {},
    resists = spec.resists or {},      -- { fire="resist", poison="immune" }
    saves = spec.saves or {},          -- { str=3, dex=2 } proficiency-added bonus
    traits = spec.traits or {},
    actions = spec.actions or {},      -- see below
    spells = spec.spells or {},        -- { {name=,level=,...}, ... }
    slotMax = spec.slots or C.SLOT_TABLE[level] or { 0, 0, 0, 0 },
    hpDice = spec.hpDice or { n = level, d = 8 },
    hitDice = spec.hitDice or 0,
    class = spec.class,
    flags = {},
    statuses = {},
    deathSaves = { success = 0, fail = 0 },
    reaction = "none",                 -- none | opportunity | shield | count
    bonusAttack = spec.bonusAttack,
    rangedAttack = spec.rangedAttack,
    passivePerception = 10 + (mods.wis or 0) + (spec.expertise and 2 or 0),
    concentration = nil,
    desc = spec.desc or "",
    icon = spec.icon,
    order = nextCid,
  }
  nextCid = nextCid + 1
  cbt.hp = cbt.hpMax

  -- A statblock can declare a cantrip attack; it is just another action with no
  -- slot behind it, and folding it in here keeps every consumer (AI scoring,
  -- threat ranges, opportunity attacks) looking at one list. The list is copied
  -- first: the spec is usually a row of Data.Bestiary, and appending here would
  -- leave that row with one more attack every time somebody spawned it.
  local actions = {}
  for i, a in ipairs(spec.actions or {}) do actions[i] = a end
  if spec.cantripAttack then
    spec.cantripAttack.isCantrip = true   -- spell damage scales with level
    actions[#actions + 1] = spec.cantripAttack
  end
  cbt.actions = actions

  -- Normalise attacks. Each action: { name, toHit|spellDc, damage, dmgType,
  --   reach, range, bonus (attack bonus override), finesse, props }
  for i, a in ipairs(cbt.actions) do
    if not a.toHit and not a.spellDc then
      a.toHit = prof + (a.ability and mods[a.ability] or mods.str)
    end
    a.reach = a.reach or (a.range and C.ft(a.range) or C.ft(5))
    a.damage = a.damage or "1"
    a.dmgType = a.dmgType or "bludgeoning"
    a.index = i
    a.hotkey = a.hotkey or ("123456789"):sub(i, i)
  end

  -- Slots: spendable per level, restored by a short/long rest.
  cbt.slots = {}
  for lvl = 1, #cbt.slotMax do cbt.slots[lvl] = cbt.slotMax[lvl] end

  byHandle[cbt.hid] = cbt
  all[#all + 1] = cbt
  return cbt
end

--- Mirror into the WC3 unit so the tooltips and the bar agree with the rules.
function Combatant.sync(cbt)
  local u = cbt.unit
  if not u then return end
  SetUnitState(u, UNIT_STATE_MAX_LIFE, math.max(1, math.floor(cbt.hpMax * C.HP_SCALE)))
  SetUnitState(u, UNIT_STATE_LIFE, math.max(0, math.floor(cbt.hp * C.HP_SCALE)))
  SetUnitMoveSpeed(u, cbt.speed * C.UNITS_PER_FOOT / 6.0)
  BlzSetUnitArmor(u, cbt.ac - 10)                  -- WC3 shows AC-10 as "armor"
  BlzSetUnitName(u, cbt.name)
  -- threat ring == the unit's own acquire range, driven by weapon reach
  local reach = C.ft(5)
  for _, a in ipairs(cbt.actions) do
    if a.reach and not a.range and a.reach > reach then reach = a.reach end
  end
  SetUnitAcquireRange(u, reach + C.FIVE_FEET * 2)
  w3.disableRealDamage(u, true)                    -- Lua deals all damage
  w3.freeze(u)
end

---------------------------------------------------------------------- accessors
function Combatant.hpScaled(cbt)  return cbt.hp * C.HP_SCALE end
function Combatant.speed(cbt)     return cbt.speed end
function Combatant.speedUnits(cbt)
  local s = cbt.speed * C.UNITS_PER_FOOT
  if DND.hasCond(cbt, "exhaustion2") or DND.hasCond(cbt, "exhaustion3") then s = s * 0.5 end
  if DND.hasCond(cbt, "restrained") or DND.hasCond(cbt, "grappled")
     or DND.hasCond(cbt, "paralyzed") or DND.hasCond(cbt, "petrified") then s = 0 end
  return s
end
function Combatant.reachUnits(cbt, action)
  return action.reach or (action.range and C.ft(action.range) or C.ft(5))
end
function Combatant.isFoeOf(a, b)  return a.side ~= b.side end

--- Best to-hit bonus available (used by the AI and by Opportunity Attacks).
--- How many times one Attack action resolves.  1 unless something granted it.
function Combatant.extraAttacks(cbt)
  local n = cbt and cbt.extraAttack
  if not n then return 1 end
  if type(n) == "boolean" then return 2 end
  return math.max(1, n)
end

function Combatant.primaryAttack(cbt)
  local best = cbt.actions[1]
  for _, a in ipairs(cbt.actions) do
    if a.toHit and (not best or a.toHit > best.toHit) then best = a end
  end
  return best
end

--- Total AC right now, including cover, Dex loss, and Dodge.
function Combatant.ac(cbt, opts)
  opts = opts or {}
  local ac = cbt.ac
  if DND.hasCond(cbt, "prone") and not opts.melee then ac = ac - 2 end
  if DND.hasCond(cbt, "paralyzed") or DND.hasCond(cbt, "stunned")
     or DND.hasCond(cbt, "unconscious") then ac = 10 + (cbt.mods.dex >= 0 and 0 or cbt.mods.dex) end
  if cbt.flags.dodge then ac = ac + 2 end
  if cbt.flags.shield then ac = ac + 5 end
  ac = ac + (opts.cover or 0)
  if opts.attackerHasAdv and DND.hasCond(cbt, "prone") then ac = ac end
  return ac
end

function Combatant.saveBonus(cbt, ability)
  local base = cbt.mods[ability] or 0
  if cbt.saves[ability] then return cbt.saves[ability] end
  return base + cbt.prof
end

function Combatant.spellSaveDc(cbt)
  local key = cbt.spellAbility or "int"
  return 8 + cbt.prof + (cbt.mods[key] or 0)
end

function Combatant.spellAttack(cbt)
  local key = cbt.spellAbility or "int"
  return cbt.prof + (cbt.mods[key] or 0)
end

---------------------------------------------------------------------- status
function Combatant.addCond(cbt, name, opts)
  if C.CONDITIONS[name] == nil then
    w3.log("unknown condition: " .. tostring(name)); return false
  end
  cbt.statuses[name] = { duration = opts and opts.duration or nil,
                         source = opts and opts.source }
  DND.ui.refreshStatus(cbt)
  return true
end

function Combatant.removeCond(cbt, name)
  if cbt.statuses[name] then
    cbt.statuses[name] = nil
    DND.ui.refreshStatus(cbt)
    return true
  end
  return false
end

function Combatant.hasCond(cbt, name)
  if type(cbt) ~= "table" or cbt.statuses == nil then
    error("hasCond(cbt, name) called with " .. type(cbt)
      .. " as the combatant (name=" .. tostring(name) .. ")", 2)
  end
  return cbt.statuses[name] ~= nil
end

function Combatant.conditionList(cbt)
  local out = {}
  for k in pairs(cbt.statuses) do out[#out + 1] = k end
  table.sort(out)
  return out
end

--- End-of-turn saves that a condition allows (e.g. frightened vs the source).
function Combatant.conditionSaves(cbt)
  local n = 0
  local names = {}
  for name in pairs(cbt.statuses) do names[#names + 1] = name end
  for _, name in ipairs(names) do
    local def = C.CONDITIONS[name]
    local save = C.SAVEABLE[name]
    if def and save and (def.endSave ~= false) then
      local ok = DND.Dice.check(Combatant.saveBonus(cbt, save), { dc = cbt.condDc or 12 })
      n = n + 1
      DND.logf("%s repeats its %s save: %s -> %s", cbt.name, save,
        C.saveLabel(save), ok.success and "ended" or "still affected")
      if ok.success then Combatant.removeCond(cbt, name) end
    end
  end
  return n
end

---------------------------------------------------------------------- display
--- The statline that goes in the tooltip / side panel. Compact on purpose.
function Combatant.statline(cbt)
  local lines = {}
  lines[#lines+1] = string.format("|cffffe066%s|r  (AC %d, %d hp, speed %d ft)",
    cbt.name, cbt.ac, cbt.hp, cbt.speed)
  local sc = {}
  for _, k in ipairs(ABILITY_KEYS) do
    sc[#sc+1] = string.upper(k) .. " " .. cbt.scores[k] .. C.signed(cbt.mods[k])
  end
  lines[#lines+1] = table.concat(sc, "  ")
  local acts = {}
  for _, a in ipairs(cbt.actions) do
    if a.toHit then acts[#acts+1] = a.name .. " " .. C.signed(a.toHit) .. " (" .. a.damage .. ")"
    else acts[#acts+1] = a.name .. " DC" .. a.spellDc end
  end
  if #acts > 0 then lines[#lines+1] = "Actions: " .. table.concat(acts, ", ") end
  if #cbt.spells > 0 then
    local sl = {}
    for lvl = 1, #cbt.slotMax do
      if cbt.slotMax[lvl] > 0 then sl[#sl+1] = C.ordinal(lvl) .. " (" .. cbt.slots[lvl] .. "/" .. cbt.slotMax[lvl] .. ")" end
    end
    lines[#lines+1] = "Slots: " .. table.concat(sl, ", ")
  end
  return table.concat(lines, "\n")
end

function Combatant.clearAll()
  for i = #all, 1, -1 do
    all[i] = nil
  end
  byHandle = {}
end

-- expose the condition helpers on DND so other modules read naturally
DND.hasCond   = Combatant.hasCond
DND.addCond   = Combatant.addCond
DND.removeCond = Combatant.removeCond

return Combatant

end

-- ------------------------------------------------------------ dnd_turns.lua
do
--[[ =========================================================================
  dnd_turns.lua — initiative and the round cycle.

  WC3 gives us nothing turn-shaped, so we keep the whole order ourselves:
  a flat list of {combatant, initiativeScore} walked one entry at a time.
  Skipping the dead, the stunned and the unconscious happens here, not in the
  state machine, so nothing can ever be "stuck" on a turn it cannot take.
========================================================================== ]]
DND = DND or {}
DND.Turns = {}
local Turns = DND.Turns
local C = DND.CONST
local Dice = DND.Dice

function Turns.new()
  return { order = {}, index = 0, round = 0, started = false, rerolled = 0 }
end

--- Roll for initiative and build the running order.
--- Tie-break: DEX mod, then a d100 coin flip (5e: DM may let them act in any
--- order; the coin keeps it fair and automated).
function Turns.rollOrder(t, combatants)
  t.order = {}
  for _, cbt in ipairs(combatants) do
    local ini = Dice.initiative(cbt.initiative, cbt.order)
    cbt.initScore = ini.score
    cbt.initNatural = ini.natural
    cbt.init = ini
    t.order[#t.order + 1] = { cbt = cbt, score = ini.score,
                              dex = cbt.initiative, coin = ini.coin,
                              nat = ini.natural }
  end
  table.sort(t.order, function(a, b)
    if a.score ~= b.score then return a.score > b.score end
    if a.dex ~= b.dex then return a.dex > b.dex end
    if a.coin ~= b.coin then return a.coin > b.coin end
    return a.cbt.cid < b.cbt.cid
  end)
  t.index = 0
  t.started = true
  return t.order
end

--- The next living creature's turn, wrapping into a new round as needed.
function Turns.next(t)
  if not t.started or #t.order == 0 then return nil end
  local guard = 0
  while true do
    t.index = t.index + 1
    if t.index > #t.order then
      t.index = 1
      t.round = t.round + 1
      DND.logf("--- ROUND %d ---", t.round)
    end
    local entry = t.order[t.index]
    if not entry then return nil end
    local cbt = entry.cbt
    guard = guard + 1
    if guard > #t.order * 3 then return nil end      -- paranoia: never hang
    if cbt.hp > 0 and not cbt.removed and not cbt.incapacitated then
      return entry
    end
    -- dead / stable / incapacitated: skip, but still let a round advance
  end
end

function Turns.current(t) return t.order[t.index] end

function Turns.peek(t, n)
  local out, i = {}, t.index
  local guard = 0
  while #out < (n or 4) and guard < 24 do
    guard = guard + 1
    i = i + 1
    if i > #t.order then i = 1 end
    local e = t.order[i]
    if e then out[#out + 1] = e end
  end
  return out
end

--- A side-to-side view for the tracker widget: who is up, who is down.
function Turns.summary(t)
  local lines = {}
  for i, e in ipairs(t.order) do
    local cbt = e.cbt
    local mark
    if cbt.hp <= 0 then mark = "|cffff5555X|r"
    elseif i == t.index then mark = "|cfffff020>" .. "|r"
    elseif i < t.index then mark = "|cff808080 | " .. "|r"
    else mark = "  " end
    lines[#lines + 1] = string.format("%s %s|cffffcc00%d|r %s",
      mark, cbt.side == C.SIDE.PARTY and "|cff66ccff" or "|cffff8866",
      e.score, cbt.name)
  end
  return lines
end

--- DM tool: force an order change mid-fight (surprise rounds, Ready actions).
function Turns.promote(t, cbt, beforeWhich)
  for i, e in ipairs(t.order) do
    if e.cbt == cbt then
      table.remove(t.order, i)
      local at = beforeWhich or 1
      table.insert(t.order, at, e)
      if i <= t.index then t.index = t.index - 1 end
      t.rerolled = t.rerolled + 1
      return true
    end
  end
  return false
end

--- Surprise: the classic first round where only the alert side acts.
function Turns.surprise(t, actorsFirst, sleepers)
  local keep = {}
  for _, cbt in ipairs(actorsFirst) do
    for i, e in ipairs(t.order) do
      if e.cbt == cbt then keep[i] = true end
    end
  end
  t.surprise = keep
  DND.logf("Surprise round: %d creature(s) act, %d are caught flat-footed.",
    (function() local n = 0 for _ in pairs(keep) do n = n + 1 end return n end)(),
    #t.order - (function() local n = 0 for _ in pairs(keep) do n = n + 1 end return n end)())
  return true
end

return Turns

end

-- ------------------------------------------------------------ dnd_resolve.lua
do
--[[ =========================================================================
  dnd_resolve.lua — the rules. Attack rolls, saves, damage, death, rests.

  Every entry point is split into "roll" and "apply" halves. That is what makes
  reactions legal here: the attacker's swing pauses in flight, the defender is
  asked for an Opportunity Attack / Shield / counterspell, and only then does
  the damage land. No coroutine, no polling, no timers — just a pending object
  that the state machine hands to Resolve.commit().
========================================================================== ]]
DND = DND or {}
DND.Resolve = {}
local Resolve = DND.Resolve
local C = DND.CONST
local Dice = DND.Dice
local w3 = DND.w3
local Combatant = DND.Combatant

---------------------------------------------------------------------- events
-- Minimal message bus so resolve.lua never has to know about the UI.
local listeners = {}
function DND.on(evt, fn)
  listeners[evt] = listeners[evt] or {}
  local l = listeners[evt]
  l[#l + 1] = fn
  return #l
end
function DND.emit(evt, a, b, c, d)
  local l = listeners[evt]
  if not l then return end
  for i = 1, #l do l[i](a, b, c, d) end
end

---------------------------------------------------------------------- helpers
local function resistMult(target, dtype)
  if not dtype then return 1 end
  local r = target.resists and target.resists[dtype]
  if not r then return 1 end
  return C.RESIST_MULT[r] or 1
end

--- Advantage sources that WC3 makes cheap to check.
--- Half / three-quarter cover, judged by counting hostile-agnostic bodies and
--- props that sit in the lane between the two. Coarse, cheap, and true to 5e.
function Resolve.coverBonus(attacker, target)
  if not DND.config.cover then return 0 end
  local d = w3.dist(attacker.unit, target.unit)
  if d <= C.FIVE_FEET then return 0 end
  local blockers = 0
  local x1, y1 = GetUnitX(attacker.unit), GetUnitY(attacker.unit)
  local x2, y2 = GetUnitX(target.unit), GetUnitY(target.unit)
  local steps = C.clamp(C.round(d / C.ft(5)), 2, 12)
  for i = 1, steps - 1 do
    local t = i / steps
    local px, py = x1 + (x2 - x1) * t, y1 + (y2 - y1) * t
    local g = CreateGroup()
    GroupEnumUnitsInRect(g, Rect(px - C.FIVE_FEET, py - C.FIVE_FEET,
                                 px + C.FIVE_FEET, py + C.FIVE_FEET), nil)
    local seen = false
    ForGroup(g, function()
      local u = GetEnumUnit()
      if not seen and u ~= target.unit and u ~= attacker.unit then
        seen = true
        blockers = blockers + 1
      end
    end)
    DestroyGroup(g)
  end
  if blockers >= 2 then return 5 end
  if blockers == 1 then return 2 end
  return 0
end

function Resolve.situationalAdv(attacker, target, action)
  local adv = 0
  local notes = {}
  -- Melee attacks against a prone, restrained, unconscious, paralyzed or
  -- stunned creature have advantage; ranged ones have DISADVANTAGE against
  -- prone. Both halves matter — a sniper should not be rewarded for shooting
  -- someone who is on the ground.
  if DND.hasCond(target, "prone") then
    if action.range then
      adv = adv - 1; notes[#notes + 1] = "prone target, shooting from range"
    else
      adv = adv + 1; notes[#notes + 1] = "target is prone"
    end
  end
  if DND.hasCond(target, "paralyzed") or DND.hasCond(target, "stunned")
     or DND.hasCond(target, "unconscious") or DND.hasCond(target, "restrained")
     or DND.hasCond(target, "grappled") then
    if not action.range then adv = adv + 1; notes[#notes + 1] = "target is easier to hit" end
  end
  -- 5e, the rule that punishes the archer: a ranged attack made from within a
  -- hostile creature's reach has disadvantage. Checked from the TARGET's side
  -- because that is where the threat is visible (the attacker does not get to
  -- consult its enemies' reach lists).
  if action.range then
    for _, other in ipairs(DND.Combat.livingOf(attacker.side == C.SIDE.PARTY
                                                and C.SIDE.FOES or C.SIDE.PARTY)) do
      local oa = Combatant.primaryAttack(other)
      if oa and not oa.range and other.hp > 0
         and w3.dist(attacker.unit, other.unit) <= (oa.reach or C.ft(5)) + C.FIVE_FEET then
        adv = adv - 1
        notes[#notes + 1] = "ranged attack from " .. other.name .. "'s reach"
        break
      end
    end
  end
  if DND.hasCond(attacker, "poisoned") or DND.hasCond(attacker, "frightened")
     or DND.hasCond(attacker, "prone") then
    adv = adv - 1; notes[#notes + 1] = "attacker hindered"
  end
  if DND.hasCond(attacker, "blinded") then adv = adv - 1; notes[#notes + 1] = "blinded" end
  if target.flags.hidden then adv = adv + 1; notes[#notes + 1] = "target is unaware" end
  if attacker.flags.invisible then adv = adv + 1; notes[#notes + 1] = "invisible" end
  return adv, notes
end

function Resolve.rangeOk(attacker, target, action)
  local need = action.reach or C.ft(5)
  if action.range then need = C.ft(action.range) end
  local d = w3.dist(attacker.unit, target.unit)
  if d > need + C.FIVE_FEET then return false, d, need end
  if action.minRange and d < C.ft(action.minRange) then return false, d, need end
  return true, d, need
end

---------------------------------------------------------------------- damage
--- Apply damage through resistances, break concentration, maybe kill.
function Resolve.applyDamage(target, amount, opts)
  opts = opts or {}
  local mult = resistMult(target, opts.type)
  local dealt = math.max(0, C.round(amount * mult))
  if opts.flatReduce then dealt = math.max(0, dealt - opts.flatReduce) end
  if dealt <= 0 then
    DND.logf("%s takes none — %s", target.name,
      mult == 0 and "immune" or (opts.flatReduce and "reduced" or "soaked"))
    return 0
  end
  local before = target.hp
  target.hp = target.hp - dealt
  if target.hp < 0 then target.hp = 0 end
  DND.emit("damage", target, dealt, before, opts)

  -- concentration: the rule everyone forgets
  if target.concentration then
    local dc = math.max(10, C.round(dealt / 2))
    local ok = Dice.check(Combatant.saveBonus(target, "con"), { dc = dc, name = "Concentration" })
    DND.logf("%s concentrates on %s — CON save DC %d: %s%s", target.name,
      target.concentration.spell, dc, ok.success and "held" or "BROKEN",
      (mult == 0 and "") or "")
    if not ok.success then Resolve.breakConcentration(target, "taking damage") end
  end

  if target.hp <= 0 then
    if opts.crit or Resolve.meleeAttackRoll(before, opts) then
      Resolve.twoDeathSaves(target, opts.crit and "critical hit" or "damage while at 0")
    else
      Resolve.enterDowned(target, opts)
    end
  end
  Combatant.sync(target)
  return dealt
end

function Resolve.meleeAttackRoll(_, opts)
  return opts and opts.at0 and true or false
end

function Resolve.breakConcentration(target, why)
  if not target.concentration then return false end
  DND.logf("%s's %s ends (%s)", target.name, target.concentration.spell, why)
  DND.emit("concentration", target, nil)
  target.concentration = nil
  if target.flags.dodging then target.flags.dodging = nil end
  if target.flags.readied then target.flags.readied = nil end
  if target.flags.shield then target.flags.shield = nil end
  return true
end

---------------------------------------------------------------------- attack
--- Damage for one swing. Split out from Resolve.attack so the "crit doubles the
--- DICE, never the modifier" rule can be tested without an encounter.
function Resolve.damageRoll(attacker, action, crit)
  local expr, declared = action.damage, true
  local dmod = action.dmod
  if dmod == nil then
    dmod = action.ability and attacker.mods[action.ability] or attacker.mods.str
    if action.finesse then dmod = math.max(attacker.mods.str, attacker.mods.dex) end
  end
  if action.noMod then dmod = 0 end
  -- A statblock may either say "1d12" (the engine adds the ability modifier,
  -- which is how a Finesse or versatile weapon stays correct) or "1d12+4" (the
  -- writer already did the arithmetic, so the engine must not add it again or
  -- every barbarian in the map hits for +STR twice).
  if not action.includesMod and not action.noMod then
    local stripped = tostring(action.damage):match("^(%d*d%d+)")
    if stripped then expr, declared = stripped, false end
  end
  local t = C.parseDice(expr)
  if not t then return { total = 0, faces = {}, label = "0", count = 0 } end
  local r = Dice.rollTemplate(t, {
    double = crit,
    bonus = declared and 0 or dmod,
    min = 1 })
  if not declared then
    r.label = string.format("%dd%d%s%d", #t.dice,
      (t.dice[1] and t.dice[1].d) or 0, (dmod >= 0 and "+" or ""), dmod)
  end
  r.label = r.label or C.diceLabel(t)      -- never nil; the log formats this
  for _, extra in ipairs(action.extraDice or {}) do
    local er = Dice.rollExpr(extra.expr, { double = crit, max = extra.max,
                                           bonus = extra.mod or 0 })
    r.total = r.total + er.total
    for _, f in ipairs(er.faces) do r.faces[#r.faces + 1] = f end
  end
  r.crit = crit and true or false
  return r
end

---------------------------------------------------------------------- attack
--- Phase 1. Returns a `pending` object, or { error = "..." }.
function Resolve.attack(attacker, target, action, opts)
  opts = opts or {}
  if not attacker or not target then return { error = "no target" } end
  if attacker.hp <= 0 then return { error = "attacker is down" } end
  -- The action-economy check lives in Combat (it needs turn state); this layer
  -- only knows whether the swing is legal in space and against this target.

  local ok = Resolve.rangeOk(attacker, target, action)
  if opts.opportunity then ok = true end
  if not ok then
    local away = C.round(C.unitsToFeet(w3.dist(attacker.unit, target.unit)))
    local need = C.round(C.unitsToFeet(action.reach or C.ft(action.range or 5)))
    return { error = string.format("%s is out of reach: %d ft away, needs %d ft",
      target.name, away, need) }
  end

  local adv, notes = Resolve.situationalAdv(attacker, target, action)
  if opts.adv then adv = adv + opts.adv end
  if opts.setAdv then adv = opts.setAdv end
  local cover = 0
  if not opts.opportunity and not action.touch then
    cover = Resolve.coverBonus(attacker, target)
  end
  local ac = Combatant.ac(target, { cover = cover, melee = not action.range })
  local bonus = (action.toHit or 0) + (opts.bonus or 0)
  -- 5e: a melee attack on an unconscious / paralyzed / restrained creature is
  -- an automatic critical hit. That is how you finish a fight in one swing.
  local autoCrit = DND.config.autoCritOnDown and (not action.range) and (
       DND.hasCond(target, "unconscious") or DND.hasCond(target, "paralyzed")
    or DND.hasCond(target, "restrained") or DND.hasCond(target, "grappled")
    or DND.hasCond(target, "stunned")
  ) or false

  local roll = Dice.attackRoll(bonus, ac, { adv = adv,
    autoCrit = autoCrit or opts.autoCrit })
  hit = roll.hit
  local dmgResult = nil
  if roll.hit then
    dmgResult = Resolve.damageRoll(attacker, action, roll.crit and DND.config.crits)
  end
  local dmg = dmgResult and dmgResult.total or 0

  return {
    rawDamage = dmg,     -- pre-resistance, for the log and for tests
    dmgRoll = dmgResult,
    attacker = attacker, target = target, action = action, roll = roll,
    ac = ac, cover = cover, adv = adv, advNotes = notes, hit = hit,
    damage = dmg, type = action.dmgType, crit = roll.crit,
    reactionWindow = Resolve.reactionsAgainst(target),
    isOpportunity = opts.opportunity,
  }
end

--- Phase 2. Runs after any reactions have been resolved.
function Resolve.commit(pending, opts)
  opts = opts or {}
  local a, t = pending.attacker, pending.target
  local roll = pending.roll
  if not pending.cancelled then
    -- Borrow WC3's swing, refuse its arithmetic: the attack animation plays off
    -- the attacker's own model, while the number below comes from the d20. With
    -- ATTACKS_ENABLED off (set in Combatant.sync) this can never double up.
    w3.playAnim(a.unit, roll.crit and "attack" or "attack1")
    -- defender's reactions may have already changed the numbers
    if t.hp <= 0 then
      DND.logf("%s is already down — %s's %s goes wide.", t.name, a.name, pending.action.name)
      return pending
    end
    if roll.hit then
      local dealt = Resolve.applyDamage(t, pending.damage, {
        type = pending.type, crit = roll.crit, at0 = pending.action.at0 })
      pending.dealt = dealt
      DND.logf("|cff88ff88%s|r hits %s: d20 %s%s%s = %d vs AC %d  |cffcccccc(%s)|r  %d %s dmg%s",
        a.name, t.name, roll.natural, C.signed(roll.mod),
        (pending.adv == 1 and " adv") or (pending.adv == -1 and " dis") or "",
        roll.total, pending.ac,
        (pending.dmgRoll and pending.dmgRoll.label) or "", dealt, pending.type,
        roll.crit and " |cffffe066CRIT!|r" or "")
      DND.ui.showHit(a, t, roll, dealt, pending)
    else
      DND.logf("|cffff6666%s|r misses %s: d20 %s%s = %d vs AC %d%s",
        a.name, t.name, roll.natural, C.signed(roll.mod), roll.total, pending.ac,
        #pending.advNotes > 0 and (" (" .. table.concat(pending.advNotes, ", ") .. ")") or "")
      DND.ui.showMiss(a, t, roll, pending.ac)
    end
  else
    DND.logf("%s's %s is interrupted by %s.", a.name, pending.action.name,
      pending.cancelReason or "a reaction")
  end
  DND.emit("attackResolved", pending)
  return pending
end

---------------------------------------------------------------------- saves
function Resolve.save(target, ability, dc, opts)
  opts = opts or {}
  if type(target) ~= "table" or target.mods == nil then
    error("Resolve.save needs a combatant to roll against (got "
      .. type(target) .. " for a " .. C.saveLabel(ability) .. " save, DC "
      .. tostring(dc) .. ")", 2)
  end
  local adv = opts.adv or 0
  -- 5e: a paralyzed or unconscious creature auto-fails Strength and Dexterity
  -- saves. That is not a -5, it is an automatic zero, so it is handled here and
  -- never left to the arithmetic (a bug I would otherwise ship).
  local autoFail
  if (DND.hasCond(target, "paralyzed") or DND.hasCond(target, "stunned")
      or DND.hasCond(target, "petrified") or DND.hasCond(target, "unconscious"))
     and (ability == "str" or ability == "dex") then
    autoFail = { 1 }
  end
  local r = Dice.d20(Combatant.saveBonus(target, ability) + (opts.bonus or 0)
      + (condFail and condFail.check or 0), adv,
      { dc = dc, autoFail = autoFail })
  r.ability = ability
  r.dc = dc
  DND.logf("%s |cffcccccc%s save|r vs DC %d: d20 %s%s = %d → %s",
    target.name, C.saveLabel(ability), dc, r.natural,
    C.signed(Combatant.saveBonus(target, ability)), r.total,
    r.success and "|cff88ff88saved|r" or "|cffff6666failed|r")
  DND.ui.showSave(target, r)
  return r
end

---------------------------------------------------------------------- spells
--- A spell is one of three shapes: attack roll, saving throw, or "auto".
function Resolve.castSpell(caster, spell, target, opts)
  opts = opts or {}
  if spell.level > 0 then
    if (caster.slots[spell.level] or 0) <= 0 then
      return { error = "no " .. C.ordinal(spell.level) .. "-level slots left" }
    end
  end
  local upcast = opts.upcast or 0
  local out = { caster = caster, spell = spell, target = target, upcast = upcast }

  if spell.needTarget and not target then
    return { error = spell.name .. " needs a target" }
  end
  if spell.needTarget and target then
    local need = C.ft(spell.range or 120)
    if w3.dist(caster.unit, target.unit) > need + C.FIVE_FEET then
      return { error = "out of range" }
    end
  end

  if spell.level > 0 and upcast == 0 then
    caster.slots[spell.level] = caster.slots[spell.level] - 1
  elseif spell.level > 0 then
    caster.slots[spell.level] = caster.slots[spell.level] - 1
  end
  out.spentSlot = spell.level

  if spell.save and not target then
    -- A save needs somebody to fail it. Area spells are resolved per-creature
    -- by the caller (see spells with aoe=), never by aiming at nothing.
    return { error = spell.name .. " is an area effect: pick the square to centre it on" }
  end
  out.dc = spell.dc or Combatant.spellSaveDc(caster)
  -- Shape 1: an area. Saves are rolled per creature in applySpellEffect, NOT
  -- here, or every target eats the damage twice. Getting this wrong showed up
  -- as "half damage on a save" dealing full damage, which is a hard test fail.
  -- Shape 2: a single target with a save. Shape 3: an attack roll. Shape 4: auto.
  if spell.aoe then
    out.area = true
  elseif spell.save then
    local r = Resolve.save(target, spell.save, out.dc, { adv = spell.adv or 0 })
    out.save = r
    out.partial = r.success and (spell.halfOnSave ~= false)
    out.damage = Resolve.spellDamage(caster, spell, upcast, out.partial)
    out.failedConc = not r.success and spell.selfConc or nil
  elseif spell.attackRoll then
    local ac = Combatant.ac(target or caster)
    local r = Dice.attackRoll(Combatant.spellAttack(caster) + (spell.toHitBonus or 0), ac)
    out.roll = r
    out.damage = r.hit and Resolve.spellDamage(caster, spell, upcast, false) or 0
  else
    out.damage = Resolve.spellDamage(caster, spell, upcast, false)
    out.auto = true
  end

  DND.logf("|cffff99ff%s|r casts %s%s at %s", caster.name, spell.name,
    upcast > 0 and (" (upcast to " .. C.ordinal(spell.level + upcast) .. ")") or "",
    target and target.name or "the area")
  return out
end

function Resolve.spellDamage(caster, spell, upcast, half)
  if not spell.damage then return 0 end
  local expr = spell.damage
  if upcast > 0 and spell.upcast then
    -- spell.upcast is a dice string per slot level above the cast level,
    -- e.g. fireball { damage="8d6", upcast="2d6" } at +2 => 8d6 + 2*levels
    local per = C.parseDice(spell.upcast)
    if per and per.dice[1] then
      local sides = per.dice[1].d
      local diceCount = #per.dice * upcast
      expr = string.format("%dd%d", diceCount, sides)
      local base = C.parseDice(spell.damage)
      if base then
        local n = #base.dice + diceCount
        expr = string.format("%dd%d", n, base.dice[1].d)
      end
      if per.mod and per.mod ~= 0 then
        expr = expr .. C.signed(per.mod * upcast)
      end
    elseif type(spell.upcast) == "number" then
      expr = spell.damage .. C.signed(spell.upcast * upcast)
    end
  end
  local r = Dice.rollExpr(expr, { max = spell.maxOnCrit })
  local d = r.total
  if half then d = math.floor(d / 2) end
  return d
end

--- For aoe= spells, run the save + damage for every creature in the blast.
--- Doing this per creature is what makes fireball feel right: allies in the
--- cone save too, and each roll is logged separately.
function Resolve.areaTargets(caster, spell, centre)
  local radius = C.ft(spell.aoe or 15)
  local cx, cy = GetUnitX(centre and centre.unit or caster.unit),
                 GetUnitY(centre and centre.unit or caster.unit)
  local hit = {}
  for _, cbt in ipairs(Combatant.all()) do
    if cbt.hp > 0 and not cbt.removed then
      local friendly = cbt.side == caster.side
      if (not friendly) or spell.affectsAllies then
        local d = w3.distPts(cx, cy, GetUnitX(cbt.unit), GetUnitY(cbt.unit))
        if d <= radius + C.FIVE_FEET then hit[#hit + 1] = cbt end
      end
    end
  end
  return hit
end

function Resolve.applySpellEffect(res)
  local spell, caster, target = res.spell, res.caster, res.target
  if spell.aoe and not res.perCreature then
    res.perCreature = {}
    for _, victim in ipairs(Resolve.areaTargets(caster, spell, target or caster)) do
      local dmg = 0
      if spell.save then
        local r = Resolve.save(victim, spell.save, res.dc or Combatant.spellSaveDc(caster))
        dmg = Resolve.spellDamage(caster, spell, res.upcast or 0, r.success)
      elseif spell.needTarget == false then
        dmg = Resolve.spellDamage(caster, spell, res.upcast or 0, false)
      end
      res.perCreature[victim.cid] = dmg
      if dmg > 0 then
        Resolve.applyDamage(victim, dmg, { type = spell.dmgType or "force" })
      end
      if spell.onHit then spell.onHit(caster, victim, res) end
    end
    res.damage = 0
    res.aoeApplied = true
  end
  if not res.aoeApplied and (res.damage or 0) > 0 and target then
    Resolve.applyDamage(target, res.damage, {
      type = spell.dmgType or "force",
      crit = res.roll and res.roll.crit })
    DND.ui.showSpellHit(caster, target, spell, res.damage)
  end
  if spell.onHit and not res.partial then
    spell.onHit(caster, target, res)
  end
  if spell.selfEffect then spell.selfEffect(caster, res) end
  if spell.concentration and not res.failedConc then
    caster.concentration = { spell = spell.name, dc = spell.dc }
    DND.logf("%s concentrates on %s", caster.name, spell.name)
  end
  DND.emit("spell", caster, spell, target, res)
  return res
end

---------------------------------------------------------------------- death
--- At 0 hp a creature either starts making death saves or simply dies, and the
--- choice is a table-level rule, not a caller's memory: `DND.config.deathSaves`
--- off means mooks stay down for good, which is the DMG shortcut and keeps a
--- 4-vs-4 brawl from becoming a rescue simulation.
function Resolve.enterDowned(cbt, opts)
  if cbt.flags.instantDeath or not DND.config.deathSaves then
    if not cbt.class then                      -- player characters still get saves
      cbt.hp = 0
      cbt.incapacitated = true
      cbt.dead = true
      DND.logf("|cffff4444%s dies outright.|r (death saves are off for mooks)", cbt.name)
      DND.ui.showDied(cbt)
      DND.emit("died", cbt)
      Combatant.sync(cbt)
      return
    end
  end

  cbt.downed = true
  cbt.deathSaves = { success = 0, fail = 0 }
  cbt.hp = 0
  DND.logf("|cffff8866%s falls to 0 hit points!|r  (mooks with the optional rule "
    .. "off just die; %s)", cbt.name,
    cbt.class and "you are at 0, so death saves begin"
        or "the DM rolls death saves for it")
  DND.ui.showDowned(cbt)
  DND.emit("downed", cbt)
end

function Resolve.twoDeathSaves(cbt, why)
  cbt.deathSaves.fail = cbt.deathSaves.fail + 2
  DND.logf("%s takes %s while unconscious — two death-save failures.", cbt.name, why)
  Resolve.checkDeathSaves(cbt)
end

function Resolve.deathSave(cbt)
  if not cbt.downed then return nil end
  local r = Dice.d20(0, 0)
  if r.natural == 1 then r.total = r.total - 1 end
  if r.natural == 20 then
    cbt.downed = false
    cbt.hp = 1
    cbt.deathSaves = { success = 0, fail = 0 }
    DND.logf("|cff88ff88%s rolls a 20 on a death save and regains 1 hp!|r", cbt.name)
    DND.emit("revived", cbt)
    return r
  end
  if r.total >= 10 then
    cbt.deathSaves.success = cbt.deathSaves.success + 1
    DND.logf("%s death save: %s = %d → success (%d/%d)",
      cbt.name, r.natural, r.total, cbt.deathSaves.success, 3)
  else
    cbt.deathSaves.fail = cbt.deathSaves.fail + 1
    DND.logf("%s death save: %s = %d → fail (%d/3)",
      cbt.name, r.natural, r.total, cbt.deathSaves.fail)
  end
  Resolve.checkDeathSaves(cbt)
  return r
end

function Resolve.checkDeathSaves(cbt)
  if cbt.deathSaves.fail >= 3 then
    cbt.incapacitated = true
    cbt.dead = true
    DND.logf("|cffff4444%s is gone. Three failures.|r", cbt.name)
    DND.emit("died", cbt)
  elseif cbt.deathSaves.success >= 3 then
    cbt.stable = true
    cbt.downed = false
    DND.logf("|cff88ff88%s is stable.|r Three successes.", cbt.name)
    DND.emit("stable", cbt)
  end
end

--- Someone can spend an action to stabilize with a DC 10 Medicine check.
function Resolve.stabilize(healer, target)
  if target.hp > 0 then return { error = "not dying" } end
  local r = Dice.check((healer.mods.wis or 0) + (healer.tools and 2 or 0),
    { dc = 10, name = "Medicine" })
  if r.success then
    target.stable = true
    target.downed = false
    target.deathSaves = { success = 3, fail = target.deathSaves.fail }
    DND.logf("|cff88ff88%s stabilises %s|r (Medicine DC 10: %s)",
      healer.name, target.name, r.total)
    DND.emit("stable", target)
  else
    DND.logf("%s fails to stabilise %s (Medicine %s)", healer.name, target.name, r.total)
  end
  return r
end

---------------------------------------------------------------------- healing
--- Hit Dice: 1 per short rest, spent as 1d{die} + CON, heals the same amount.
function Resolve.spendHitDie(cbt)
  if cbt.hitDice <= 0 then return { error = "no Hit Dice left" } end
  local die = cbt.hpDice and cbt.hpDice.d or 8
  local r = Dice.rollExpr("1d" .. die)
  local heal = math.max(1, r.total + (cbt.mods.con or 0))
  cbt.hitDice = cbt.hitDice - 1
  return Resolve.heal(cbt, heal, "1d" .. die .. C.signed(cbt.mods.con or 0))
end

function Resolve.heal(cbt, amount, label)
  local before = cbt.hp
  cbt.hp = math.min(cbt.hpMax, cbt.hp + amount)
  local got = cbt.hp - before
  if cbt.hp > 0 then cbt.downed = false end
  Combatant.sync(cbt)
  DND.logf("|cff88ff88%s|r recovers %d hp%s", cbt.name, got,
    label and (" (" .. label .. ")") or "")
  DND.ui.showHeal(cbt, got)
  DND.emit("heal", cbt, got)
  return { healed = got }
end

---------------------------------------------------------------------- rests
function Resolve.shortRest(cbt)
  local n = math.max(1, math.floor(cbt.level / 2))
  local spend = 0
  for _ = 1, n do
    if cbt.hitDice > 0 then
      Resolve.spendHitDie(cbt)
      spend = spend + 1
    end
  end
  for lvl = 1, #cbt.slotMax do
    if cbt.slotMax[lvl] > 0 and lvl <= 2 then cbt.slots[lvl] = cbt.slotMax[lvl] end
  end
  DND.logf("%s takes a short rest: %d Hit Die spent, 1st/2nd-level slots back.",
    cbt.name, spend)
  DND.emit("shortRest", cbt)
  return spend
end

function Resolve.longRest(cbt)
  cbt.hp = cbt.hpMax
  cbt.hitDice = cbt.level
  cbt.downed, cbt.stable = false, false
  cbt.deathSaves = { success = 0, fail = 0 }
  for lvl = 1, #cbt.slotMax do cbt.slots[lvl] = cbt.slotMax[lvl] end
  -- keys first, then clear (same pairs()-mutation hazard as dnd_combat)
  local cleared = {}
  for k in pairs(cbt.statuses) do cleared[#cleared + 1] = k end
  for _, k in ipairs(cleared) do cbt.statuses[k] = nil end
  cbt.concentration = nil
  Combatant.sync(cbt)
  DND.logf("%s finishes a long rest.", cbt.name)
  DND.emit("longRest", cbt)
  return true
end

---------------------------------------------------------------------- reactions
--- Which reactions does this creature currently have armed and legal?
function Resolve.reactionsAgainst(target)
  local out = {}
  if target.reaction == "opportunity" then
    out[#out + 1] = { key = "attack", label = "Opportunity Attack",
                      desc = "free melee attack before the mover leaves your reach" }
  end
  if target.reaction == "shield" then
    out[#out + 1] = { key = "shield", label = "Shield (+5 AC)",
                      desc = "reaction; also deflects Magic Missile" }
  end
  if target.flags.readied then
    out[#out + 1] = { key = "ready", label = "Ready: " .. target.flags.readied.attack.name,
                      desc = "your readied attack" }
  end
  return out
end

function Resolve.takeReaction(cbt, which, pending)
  if cbt.reactionTaken then return { error = "reaction already used this round" } end
  if which == "attack" and pending then
    local atk = cbt.flags.pendingOpportunity and cbt.flags.pendingOpportunity.action
              or Combatant.primaryAttack(cbt)
    if not atk then return { error = "no melee attack" } end
    cbt.reactionTaken = true
    -- swing at whoever provoked (pending.reactionFor), falling back to the
    -- mover recorded by the caller. Never at pending.attacker: in the
    -- opportunity flow that is this very creature, which is how a guard ends up
    -- faithfully attacking itself.
    local victim = pending.reactionFor or pending.target or pending.attacker
    if victim == cbt then victim = pending.target end
    if victim == cbt then return { error = "no valid provoking creature" } end
    local p = Resolve.attack(cbt, victim, atk, { opportunity = true, force = true })
    if p.error then return p end
    Resolve.commit(p)
    return { ok = true, kind = "opportunity", pending = p }
  elseif which == "shield" then
    cbt.reactionTaken = true
    cbt.flags.shield = true
    if pending then
      pending.ac = pending.ac + 5
      pending.roll = Dice.attackRoll(pending.action.toHit or 0, pending.ac,
        { adv = pending.adv, autoCrit = pending.roll.critOnly })
      pending.hit = pending.roll.hit
      pending.damage = 0
      if pending.roll.hit then
        local r = Dice.rollExpr(pending.action.damage,
          { double = pending.roll.crit,
            bonus = pending.action.finesse and math.max(cbt.mods.str, cbt.mods.dex) or cbt.mods.str })
        pending.damage = r.total
        pending.roll.dmgLabel = r.label
      end
      DND.logf("|cff99ccff%s|r raises a shield — AC is now %d, the attack "
        .. "is rerolled against it.", cbt.name, pending.ac)
      if not pending.hit then pending.cancelled = false end
    end
    return { ok = true, kind = "shield" }
  end
  return { error = "no such reaction" }
end

--- Called by the move code: anyone whose reach you just left gets a shot.
--- Position-based (raw x/y, not a unit handle) so the AI can ask the same
--- question about a square it has not stepped into yet.
function Resolve.opportunitiesAt(mover, ox, oy, nx, ny, disengaged, allowShield)
  local out = {}
  if disengaged then return out end
  if mover.flags.invisible then return out end
  for _, foe in ipairs(Combatant.all()) do
    if foe ~= mover and foe.side ~= mover.side and foe.hp > 0 and not foe.removed
       and not foe.reactionTaken then
      local def = nil
      for name in pairs(foe.statuses) do def = C.CONDITIONS[name] or def end
      local incap = DND.hasCond(foe, "paralyzed") or DND.hasCond(foe, "stunned")
                 or DND.hasCond(foe, "unconscious") or DND.hasCond(foe, "petrified")
      local atk = Combatant.primaryAttack(foe)
      if atk and not incap then
        local reach = atk.reach or C.ft(5)
        local wasIn = w3.distPts(ox, oy, GetUnitX(foe.unit), GetUnitY(foe.unit)) <= reach + C.FIVE_FEET
        local nowOut = w3.distPts(nx, ny, GetUnitX(foe.unit), GetUnitY(foe.unit)) > reach + C.FIVE_FEET
        -- ranged attackers do not get a free swing for you walking away
        if wasIn and nowOut and not atk.range then
          out[#out + 1] = { foe = foe, atk = atk, allowShield = allowShield }
        end
      end
    end
  end
  return out
end

function Resolve.opportunitiesOnMove(mover, fromX, fromY, disengaged)
  local nx, ny = GetUnitX(mover.unit), GetUnitY(mover.unit)
  return Resolve.opportunitiesAt(mover, fromX, fromY, nx, ny, disengaged, true)
end

---------------------------------------------------------------------- stealth
function Resolve.stealth(cbt, dc)
  local r = Dice.check(cbt.mods.dex + (cbt.flags.expertiseStealth and cbt.prof or 0),
    { dc = dc or 999 })
  if r.total >= (dc or 999) or not dc then
    cbt.flags.hidden = true
    DND.logf("%s hides (Stealth %s). Attacks from hiding have advantage; "
      .. "the target loses its DEX-to-AC until revealed.", cbt.name, r.total)
  else
    DND.logf("%s fails to hide (Stealth %s vs DC %d).", cbt.name, r.total, dc or 0)
  end
  return r
end

function Resolve.perception(cbt, dc)
  return Dice.check((cbt.mods.wis or 0) + cbt.prof, { dc = dc })
end

return Resolve

end

-- ------------------------------------------------------------ dnd_combat.lua
do
--[[ =========================================================================
  dnd_combat.lua — the turn state machine.

  WC3 has no "end my turn" and no pause-all-units, so this file manufactures
  both. The whole design rests on three moves:

    1. Every combatant is frozen (PauseUnit + pathing off + attacks disabled)
       at all times. Real time therefore cannot hurt anybody.
    2. Only the creature whose initiative it is gets unfrozen, and only for
       exactly as long as its action economy allows.
    3. Damage never comes from WC3's attack engine — the swing animation is
       borrowed, the numbers come from dnd_resolve.lua.

  The machine is event-driven, not timer-driven: a "tick" happens when a
  player presses something, and on AI turns when the AI callback returns.
  That means no polling, no race conditions, and no desync surface at all.
========================================================================== ]]
DND = DND or {}
DND.Combat = {}
local Combat = DND.Combat
local C = DND.CONST
local w3 = DND.w3
local Dice = DND.Dice
local Resolve = DND.Resolve
local Combatant = DND.Combatant
local Turns = DND.Turns

Combat.state = {
  running = false,
  phase = C.PHASE.IDLE,
  turn = nil,             -- { cbt, score }
  pending = nil,          -- attack awaiting a reaction / commit
  armed = nil,            -- { action=, kind= } the selected action
  moves = {},             -- undo stack for this turn
  encounter = nil,
  debug = false,
}
local S = Combat.state
Combat.turns = Turns.new()
local turns = Combat.turns

---------------------------------------------------------------------- logging
DND.logLines = DND.logLines or {}
function DND.logf(fmt, ...)
  local ok, msg = pcall(string.format, fmt, ...)
  if not ok then msg = tostring(fmt) end
  -- strip WC3 colour codes for the plain-text log. The pattern has to be
  -- |c + 8 hex digits, exactly; a sloppy version here ate a visible character.
  msg = (msg:gsub("|c%x%x%x%x%x%x%x%x", "")):gsub("|r", "")
  local n = #DND.logLines + 1
  DND.logLines[n] = msg
  if n > 400 then table.remove(DND.logLines, 1) end
  if DND.ui and DND.ui.pushLog then DND.ui.pushLog(msg) end
  if DND.testVerbose then print("[log] " .. msg) end
end
function DND.logError(msg)
  DND.logf("|cffff5555ERROR:|r " .. tostring(msg))
  if not DND.testMode then w3.log("ERROR: " .. tostring(msg)) end
end

---------------------------------------------------------------------- helpers
local function livingOn(side) return Combatant.living(side) end

function Combat.enemiesOf(cbt)
  local out = {}
  for _, other in ipairs(Combatant.all()) do
    if other ~= cbt and other.side ~= cbt.side and other.hp > 0 and not other.removed then
      out[#out + 1] = other
    end
  end
  table.sort(out, function(a, b) return a.hp < b.hp end)
  return out
end

--- Living creatures on the given side (a `side` is required, unlike
--- Combatant.living's "everybody" default). Exposed here because the rules layer
--- reaches for threat lists through DND.Combat.
function Combat.livingOf(side)
  return Combatant.livingOf(side)
end

--- Threatened = an armed foe is inside someone's reach.
function Combat.threatenedBy(cbt)
  local out = {}
  for _, foe in ipairs(Combat.enemiesOf(cbt)) do
    local atk = Combatant.primaryAttack(foe)
    if atk and w3.dist(foe.unit, cbt.unit) <= (atk.reach or C.ft(5)) + C.FIVE_FEET then
      out[#out + 1] = foe
    end
  end
  return out
end

---------------------------------------------------------------------- lifecycle
function Combat.startEncounter(name, combatants, opts)
  opts = opts or {}
  if S.running then Combat.abort("restart") end
  if #combatants < 2 then DND.logError("encounter needs at least two combatants") return end
  S.running = true
  -- Whatever the caller adds to this record (delve room, XP, carry-on) rides
  -- along to the end of the fight, where Data.afterVictory reads it back.
  S.encounter = { name = name or "Skirmish", round = 0, startedAt = 0,
                  rounds = 0, surprise = opts.surprise,
                  carryOn = opts.carryOn, rest = opts.rest,
                  encounterKey = opts.encounterKey, index = opts.encounterIndex,
                  bounds = opts.bounds }
  for _, cbt in ipairs(combatants) do
    cbt.reaction = "none"
    cbt.reactionTaken = false
    cbt.flags = cbt.flags or {}
    Combatant.sync(cbt)
    if opts.rest ~= false then
      cbt.hitDice = cbt.hitDice > 0 and cbt.hitDice or cbt.level
      for lvl = 1, #cbt.slotMax do cbt.slots[lvl] = cbt.slotMax[lvl] end
    end
  end
  turns = Turns.new(); Combat.turns = turns
  DND.logf("|cffffe066== %s ==|r  Roll for initiative!", name or "Encounter")
  local order = Turns.rollOrder(turns, combatants)
  for _, e in ipairs(order) do
    DND.logf("  %-18s %s%s  init %d", e.cbt.name,
      e.cbt.side == C.SIDE.PARTY and "(party)" or "(foes)",
      (""):rep(0), e.score)
  end
  DND.ui.buildTracker()
  if opts.surprise then Turns.surprise(turns, opts.surprise, {}) end
  Combat.nextTurn()
  return true
end

function Combat.abort(reason)
  S.running = false
  S.phase = C.PHASE.IDLE
  S.turn = nil
  S.pending = nil
  S.armed = nil
  for _, cbt in ipairs(Combatant.all()) do
    w3.unfreeze(cbt.unit, false)
    cbt.flags = {}
    cbt.concentration = nil
  end
  DND.ui.clear()
  DND.logf("Combat ended (%s).", reason)
end

--- Victory/defeat screen hook; the real map overrides it.
function Combat.checkEnd()
  local party, foes = #livingOn(C.SIDE.PARTY), #livingOn(C.SIDE.FOES)
  if party == 0 then
    DND.logf("|cffff4444The party is broken. Defeat.|r")
    local rec = S.encounter
    Combat.abort("wipe")
    -- Same hook as a victory, with 0 XP and a result string: a delve has to be
    -- able to charge you for losing, and this file should not know what losing
    -- costs. See Data.afterVictory.
    if DND.afterCombatHook then DND.afterCombatHook(0, rec, "defeat") end
    if DND.onDefeat then DND.onDefeat() end
    return true
  end
  if foes == 0 then
    DND.logf("|cff88ff88The field is yours. Victory.|r")
    local xp = 0
    for _, cbt in ipairs(Combatant.all()) do
      if cbt.side == C.SIDE.FOES then xp = xp + (cbt.xp or (cbt.level * 50)) end
    end
    -- "each" is per head of the party as it STARTED, not per survivor: the
    -- difference matters in a delve, where the roster shrinks mid-run. The
    -- encounter record knows how many walked in; `party` is how many are left.
    if xp > 0 and DND.config.xpTrack ~= false then
      local heads = (S.encounter and S.encounter.partyCount) or party
      if heads < 1 then heads = 1 end
      DND.logf("Award %d XP (%d each).", xp, math.ceil(xp / heads))
    end
    -- What the award MEANS (levels, hit points carried into the next room, the
    -- toll of a wipe) is the adventure layer's business, so it is a hook this
    -- file only offers. dnd_data.lua installs it; a real map can replace it.
    local rec = S.encounter
    Combat.abort("victory")
    if DND.afterCombatHook then DND.afterCombatHook(xp, rec) end
    if DND.onVictory then DND.onVictory(xp) end
    return true
  end
  return false
end

---------------------------------------------------------------------- turn flow
function Combat.nextTurn()
  if not S.running then return end
  if Combat.checkEnd() then return end
  local entry = Turns.next(turns)
  if not entry then Combat.abort("no valid turns") return end
  S.turn = entry
  S.moves = {}
  S.armed = nil
  S.pending = nil
  local cbt = entry.cbt
  DND.logf("|cffffcc00Round %d|r — %s's turn%s", turns.round, cbt.name,
    cbt.side == C.SIDE.PARTY and "" or " (invaders)")
  Combat.beginTurn(cbt)
end

function Combat.beginTurn(cbt)
  S.phase = C.PHASE.BEGIN
  -- A reaction refreshes at the START OF YOUR OWN ROUND, not at the start of
  -- each creature's turn. Clearing it here would hand every defender a fresh
  -- opportunity attack on every single move anywhere on the board.
  if turns.index <= 1 and turns.round > 0 then
    for _, other in ipairs(Combatant.all()) do other.reactionTaken = false end
  end
  cbt.flags.disengaged = nil
  cbt.flags.movedThisTurn = nil
  cbt.movementLeft = Combatant.speedUnits(cbt)
  cbt.movementTotal = cbt.movementLeft
  cbt.actionUsed = false
  cbt.bonusUsed = false
  local stale = {}
  for k in pairs(cbt.flags) do
    if k == "dodge" or k == "shield" or k == "readied" then stale[#stale+1] = k end
  end
  for _, k in ipairs(stale) do cbt.flags[k] = nil end
  Combat.freeActions(cbt)

  -- prone costs half your movement to rise (5e: standing uses 1/2 your speed)
  if DND.hasCond(cbt, "prone") then
    cbt.movementLeft = math.floor(cbt.movementLeft / 2)
    DND.removeCond(cbt, "prone")
    DND.logf("%s stands, spending half its movement.", cbt.name)
  end

  -- incapacitated conditions burn the turn but still let a save happen
  local skip = false
  for name in pairs(cbt.statuses) do
    local def = C.CONDITIONS[name]
    if def and def.skipTurn then skip = true end
  end
  if cbt.downed then skip = true end

  w3.lookAt(cbt.unit)
  DND.ui.setActive(cbt)

  if skip then
    S.phase = C.PHASE.END
    local why = cbt.downed and "unconscious" or "incapacitated"
    DND.logf("%s cannot act (%s).", cbt.name, why)
    if cbt.downed then Resolve.deathSave(cbt) end
    -- Snapshot the KEYS only, then mutate after the walk. removeCond touches
    -- cbt.statuses, and deleting a key while pairs() is mid-traversal is
    -- undefined in Lua 5.1: the loop can hand you a nil value, and the crash
    -- surfaces as "attempt to index a nil value" several frames away from the
    -- line that actually caused it.
    local due = {}
    for name in pairs(cbt.statuses) do due[#due + 1] = name end
    for _, name in ipairs(due) do
      local st = cbt.statuses[name]
      if st and st.duration then
        st.duration = st.duration - 1
        if st.duration <= 0 then DND.removeCond(cbt, name) end
      end
    end
    w3.after(DND.testMode and 0 or 0.6, function() Combat.endTurn(cbt) end)
    return
  end

  -- now they can actually act
  w3.unfreeze(cbt.unit, false)          -- attacks stay disabled: Lua deals damage
  DND.ui.showActions(cbt)
  if cbt.side == C.SIDE.PARTY then
    S.phase = C.PHASE.ACTION
    DND.ui.promptPlayer(cbt)
  else
    S.phase = C.PHASE.ENEMY
    if DND.config.aiEnabled ~= false and DND.ai and DND.ai.takeTurn then
      DND.ai.takeTurn(cbt, function() Combat.endTurn(cbt) end)
    else
      -- With the AI off the turn simply waits. Ending it here (the obvious
      -- fallback) silently skips every invader and makes "aiEnabled = false"
      -- look broken instead of useful: it is how you run a hot-seat session, a
      -- scripted scene, or a test that inspects a turn mid-flight.
      DND.ui.setHint(cbt.name .. "'s turn is on hold (AI disabled).")
    end
  end
end

--- Free things that cost nothing, recomputed each turn.
function Combat.freeActions(cbt)
  cbt.canStep = true
  cbt.interactionsLeft = 1
end

function Combat.endTurn(cbt)
  cbt = cbt or (S.turn and S.turn.cbt)
  if not cbt then
    -- Called with no argument after the order moved on: end whoever currently
    -- holds the turn rather than silently doing nothing. A no-op here leaves
    -- the game frozen mid-turn, which is the worst possible failure to debug.
    local e = S.turn or DND.Combat.turns.order[DND.Combat.turns.index]
    cbt = e and e.cbt
  end
  if not cbt then
    DND.logf("endTurn: no active creature, ignoring")
    return
  end
  S.phase = C.PHASE.END
  -- concentration persists; conditions tick at the end of the sufferer's turn
  Combatant.conditionSaves(cbt)
  w3.freeze(cbt.unit)
  cbt.movementLeft = 0
  DND.ui.hideActions(cbt)
  DND.ui.clearActive()
  Combat.revokeTargetingAbility(cbt)
  S.armed, S.pending, S.reactionPrompt = nil, nil, nil
  w3.after(DND.testMode and 0 or 0.12, function() Combat.nextTurn() end)
end

---------------------------------------------------------------------- movement
--- A single "step": a move order for up to `ft` feet. Validated before it is
--- issued, so WC3 can never cheat the budget by pathing somewhere illegal.
function Combat.move(f, opts)
  opts = opts or {}
  local cbt = S.turn and S.turn.cbt
  if not cbt then return { error = "not your turn" } end
  -- Explicit actor: silently moving whoever happens to hold the turn is the
  -- kind of bug that hides in an AI refactor, so we refuse it out loud.
  if opts.who and opts.who ~= cbt then
    return { error = "not " .. opts.who.name .. "'s turn" }
  end
  if S.phase == C.PHASE.REACTION then return { error = "resolve the reaction first" } end
  if cbt.side == C.SIDE.PARTY and S.phase == C.PHASE.ENEMY then
    return { error = "wait for your turn" }
  end
  local u = cbt.unit
  local x1, y1 = GetUnitX(u), GetUnitY(u)
  -- `0/0` in a trait's maths, or a position read off a unit that is already gone,
  -- lands here as nan.  Guard it at the one place every move goes through: in the
  -- real game SetUnitX(nan) gives you a creature that can never be moved, targeted
  -- or looked at again, and `nan <= 0.01` is false, so the distance check below
  -- would not have caught it.
  if not (f.x == f.x and f.y == f.y) then return { error = "nowhere to go" } end
  local d = w3.distPts(x1, y1, f.x, f.y)
  if not (d > 0.01) then return { error = "already there" } end
  -- The remaining budget is the only hard limit; a destination farther than one
  -- turn of movement is not an error, you just spend it all walking that way.
  -- There is deliberately no extra per-order clamp, because the AI depends on
  -- being able to approach across a big battlefield one move at a time.
  cbt.movementLeft = cbt.movementLeft or 0
  if opts.dash and not cbt.flags.dashCredited then
    cbt.movementLeft = cbt.movementLeft + cbt.speed * C.UNITS_PER_FOOT
    cbt.flags.dashCredited = true
  end
  if d > cbt.movementLeft + C.FIVE_FEET * 0.5 then
    -- clamp to the budget instead of refusing: keeps 6 seconds of movement
    local t = cbt.movementLeft / d
    f = { x = x1 + (f.x - x1) * t, y = y1 + (f.y - y1) * t }
    d = cbt.movementLeft
  end

  -- a frightened creature may not end a move nearer the source of its fear
  local fear = cbt.statuses.frightened
  if fear and fear.source then
    local src = Combatant.byId(fear.source)
    if src and w3.distPts(f.x, f.y, GetUnitX(src.unit), GetUnitY(src.unit))
              < w3.dist(u, src.unit) - C.FIVE_FEET then
      return { error = "frightened: cannot move closer to " .. src.name }
    end
  end

  local before = { x = x1, y = y1, left = cbt.movementLeft }
  w3.moveTo(u, f.x, f.y)
  cbt.movementLeft = math.max(0, cbt.movementLeft - d)
  cbt.flags.movedThisTurn = true
  S.moves[#S.moves + 1] = before
  DND.ui.updateMovement(cbt)
  DND.logf("%s moves %.0f ft (%.0f ft left).", cbt.name,
    C.round(C.unitsToFeet(d)), C.round(C.unitsToFeet(cbt.movementLeft)))

  -- leaving reach?  Opportunity attacks happen here, mid-move, exactly as 5e wants
  local react = Resolve.opportunitiesOnMove(cbt, before.x, before.y,
    cbt.flags.disengaged)
  if #react > 0 then
    Combat.offerOpportunities(cbt, react)
  end
  return { ok = true, distance = d }
end

function Combat.undoMove()
  local cbt = S.turn and S.turn.cbt
  if not cbt or #S.moves == 0 then return { error = "nothing to undo" } end
  local prev = table.remove(S.moves)
  w3.moveTo(cbt.unit, prev.x, prev.y)
  cbt.movementLeft = prev.left
  DND.ui.updateMovement(cbt)
  -- note: opportunity attacks already resolved cannot be un-triggered; the
  -- undo is a courtesy, the DM console says so in the log.
  DND.logf("%s steps back. (Opportunity attacks already taken stay taken.)", cbt.name)
  return { ok = true }
end

---------------------------------------------------------------------- attacking
---------------------------------------------------------------------- targeting
--- Optional sugar: while an action is armed, grant the creature a real WC3
--- ability (AATK / AMOV from dnd_data.js) so the native targeting cursor and
--- its range ring do the pointing for us. This is cosmetic wiring over the same
--- rules path: the ability's own damage is 1d0+0 and the cast still funnels
--- through executeOn, so nothing can bypass the d20. If the object data is not
--- compiled into the map, UnitAddAbility fails and we quietly stay on the key
--- path — which is why the flag defaults off rather than being required.
function Combat.grantTargetingAbility(cbt, code)
  if not DND.config.nativeTargeting or not cbt or not cbt.unit then return false end
  if not code then return false end
  if not UnitAddAbility(cbt.unit, code) then
    DND.logf("nativeTargeting needs dnd_data.js compiled (missing ability %s)",
      string.format("%08X", code))
    return false
  end
  SetUnitAbilityLevel(cbt.unit, code, 1)
  BlzSetUnitAbilityCooldown(cbt.unit, code, 1, 0)
  cbt.flags.grantedTargeting = code
  DND.ui.setHint(DND.ui.state.hint .. "  (right-click to aim)")
  return true
end

function Combat.revokeTargetingAbility(cbt)
  local code = cbt and cbt.flags and cbt.flags.grantedTargeting
  if code then
    UnitRemoveAbility(cbt.unit, code)
    cbt.flags.grantedTargeting = nil
  end
end

--- Arm an action. opts.force is for the AI's "swing anyway so the rules say no"
--- fallback, and for a DM nudging a scripted moment; it does NOT skip range,
--- targets, or slot costs.
function Combat.armAction(kind, index, opts)
  opts = opts or {}
  local cbt = S.turn and S.turn.cbt
  if not cbt then return { error = "not your turn" } end
  if opts.who and opts.who ~= cbt then return { error = "not " .. opts.who.name .. "'s turn" } end
  if kind == "attack" then
    local a = cbt.actions[index or 1]
    if not a then return { error = "no such attack" } end
    if cbt.actionUsed and not a.bonus then return { error = "action already used" } end
    S.armed = { kind = "attack", action = a, index = index or 1 }
    Combat.grantTargetingAbility(cbt, DND.RC.ATTACK)
    DND.ui.showTargeting(cbt, a)
    return { ok = true }
  elseif kind == "spell" then
    local sp = cbt.spells[index]
    if not sp then return { error = "no such spell" } end
    if cbt.actionUsed and not sp.bonus then return { error = "action already used" } end
    if sp.level > 0 and (cbt.slots[sp.level] or 0) <= 0 then
      return { error = "no " .. C.ordinal(sp.level) .. " slots left" }
    end
    S.armed = { kind = "spell", spell = sp, index = index }
    Combat.grantTargetingAbility(cbt, DND.RC.ATTACK)
    DND.ui.showTargeting(cbt, sp)
    return { ok = true }
  end
  return { error = "unknown action" }
end

function Combat.cancelAction()
  S.armed = nil
  Combat.revokeTargetingAbility(S.turn and S.turn.cbt)
  DND.ui.clearTargeting()
  return { ok = true }
end

--- Resolve the armed action against a chosen target.
function Combat.executeOn(target, opts)
  opts = opts or {}
  local cbt = S.turn and S.turn.cbt
  if not cbt or not S.armed then return { error = "nothing selected" } end
  if opts.who and opts.who ~= cbt then return { error = "not " .. opts.who.name .. "'s turn" } end
  local armed = S.armed
  local a = armed.action or armed.spell
  if not a then
    S.armed = nil
    Combat.revokeTargetingAbility(cbt)
    return { error = "the armed action vanished (statblock changed mid-turn?)" }
  end
  if target and target.hp <= 0 then return { error = "already down" } end

  if armed.kind == "spell" then
    local res = Resolve.castSpell(cbt, armed.spell, target)
    if res.error then return res end
    if armed.spell.bonus then cbt.bonusUsed = true else cbt.actionUsed = true end
    Resolve.applySpellEffect(res)
    if armed.spell.needConcSave then
      res.failedConc = not Resolve.save(cbt, "con", armed.spell.dc or 10).success
    end
    S.armed = nil
    Combat.revokeTargetingAbility(cbt)
    DND.ui.clearTargeting()
    Combat.maybeAutoEnd(cbt)
    return res
  end

  local pending = Resolve.attack(cbt, target, a, force and { force = true } or nil)
  if pending.error then return pending end
  cbt.actionUsed = not a.bonus and true or cbt.actionUsed
  if a.bonus then cbt.bonusUsed = true end
  S.armed = nil
  S.pending = pending
  Combat.revokeTargetingAbility(cbt)
  DND.ui.clearTargeting()
  -- Held for the whole multi-swing action: `maybeAutoEnd` schedules the turn's end on
  -- a timer, and in test mode that timer is instantaneous, which would end the turn
  -- between the first swing and the second.  A player would see one attack and no
  -- explanation, and the flag is cheaper than reasoning about timer order.
  cbt.flags.inAction = true
  local res = Combat.resolvePending()

  -- Extra Attack, and it lives here rather than in Resolve.attack because it is a
  -- question about the Action, not about the swing: the second attack is part of the
  -- same action, which `cbt.actionUsed` has already been spent on.  The AI gets it
  -- for free, because the AI calls these same two entry points.
  --
  -- Deliberately no reaction window per extra swing: a defender has one reaction per
  -- turn, and the first swing already spent the trigger.  Prompting again would sell
  -- the player a reaction they are not entitled to.
  for i = 2, Combatant.extraAttacks(cbt) do
    if a.bonus or not res or res.error then break end
    if target.hp <= 0 or cbt.hp <= 0 then break end
    if not S.turn or S.turn.cbt ~= cbt then break end   -- the fight moved on under us
    DND.logf("|cffffe066Extra Attack|r — %s swings %s again.", cbt.name, a.name)
    local more = Resolve.attack(cbt, target, a, force and { force = true } or nil)
    if more.error then
      res = more
      break
    end
    res = Resolve.commit(more)
    res.attacks = i
  end
  cbt.flags.inAction = nil
  Combat.maybeAutoEnd(cbt)
  return res
end

--- Insert the reaction window, then commit.  For AI defenders the reactions are
--- taken automatically; for the player's side we stop and wait for input.
function Combat.resolvePending()
  local pending = S.pending
  if not pending then return { error = "no pending attack" } end
  local defender = pending.target
  local avail = pending.reactionWindow
  if (not avail) or #avail == 0 or not DND.config.reactions then
    Resolve.commit(pending)
    S.pending = nil
    Combat.maybeAutoEnd(defender)
    Combat.maybeAutoEnd(pending.attacker)
    return pending
  end
  -- The defender is asked if it belongs to a side that plays itself; every
  -- other side resolves its own reactions with no prompt.
  if defender.side ~= C.SIDE.PARTY or DND.config.aiPlaysParty or not DND.config.reactions then
    -- AI reacts greedily: take the best option it has
    for _, r in ipairs(avail) do
      if r.key == "attack" then Resolve.takeReaction(defender, "attack", pending) break
      elseif r.key == "shield" then Resolve.takeReaction(defender, "shield", pending) break end
    end
    Resolve.commit(pending)
    S.pending = nil
    Combat.maybeAutoEnd(pending.attacker)
    return pending
  end
  -- human defender gets the prompt; the attack hangs in mid-air meanwhile
  S.phase = C.PHASE.REACTION
  S.reactionPrompt = { kind = "defense", cbt = defender, options = avail, pending = pending }
  DND.ui.promptReaction(defender, avail, pending)
  return pending
end

--- `choice` is "hold" or a reaction key. Routes to whichever flow armed the
--- prompt: a defender answering a swing, or a foe answering a movement.
function Combat.answerReaction(choice)
  local prompt = S.reactionPrompt
  if not prompt then return { error = "no reaction requested" } end
  local cbt, pending = prompt.cbt, prompt.pending
  S.reactionPrompt = nil
  if choice and choice ~= "hold" then
    Resolve.takeReaction(cbt, choice, pending)
  else
    DND.logf("%s holds its reaction.", cbt.name)
  end
  if prompt.kind == "defense" then
    Resolve.commit(pending)
    S.pending = nil
    S.phase = C.PHASE.ACTION
  end
  DND.ui.clearReaction()
  if Combat.drainQueuedOpportunities() then return { ok = true, queued = true } end
  Combat.maybeAutoEnd(cbt)
  return { ok = true }
end

--- Opportunity attacks on movement.  A player-side defender is asked; an AI
--- defender just swings.  Prompts are queued so leaving two enemies' reach
--- spends the single reaction on the first of them, exactly as 5e rules go.
function Combat.offerOpportunities(mover, react)
  for _, r in ipairs(react) do
    local foe = r.foe
    -- Direction matters and is easy to flip: the *reacting* creature swings at
    -- the one that just walked away.
    local pending = { attacker = foe, target = mover, action = r.atk,
                      isOpportunity = true, advNotes = {}, reactionWindow = nil,
                      reactionFor = mover }
    -- Ask the DEFENDER, not "the side that is not acting". Keying this off
    -- whose turn it is was my first instinct and it is wrong: on an invader's
    -- turn the reactor IS the player, and that is exactly when a free attack
    -- against them deserves a "do you take it?" prompt.
    if foe.side ~= C.SIDE.PARTY or DND.config.aiPlaysParty or not DND.config.reactions then
      foe.reactionTaken = false
      Resolve.takeReaction(foe, "attack", pending)
    elseif not S.reactionPrompt then
      S.phase = C.PHASE.REACTION
      S.reactionPrompt = { kind = "opportunity", cbt = foe, pending = pending,
                           options = { { key = "attack", label = "Opportunity Attack" } } }
      DND.ui.promptReaction(foe, S.reactionPrompt.options, pending)
    else
      -- a second foe also wants a bite; the mover is already inside reach so we
      -- let the queue drain one at a time when the first prompt closes.
      foe.flags.pendingOpportunity = pending
    end
  end
end

--- Called after a prompt closes: anyone still owed an opportunity gets it.
function Combat.drainQueuedOpportunities()
  for _, cbt in ipairs(Combatant.all()) do
    local p = cbt.flags.pendingOpportunity
    if p then
      cbt.flags.pendingOpportunity = nil
      cbt.reactionTaken = false
      Resolve.takeReaction(cbt, "attack", p)
      return true     -- one at a time; re-enters from answerReaction
    end
  end
  return false
end

---------------------------------------------------------------------- other acts
function Combat.useAction(kind, opts)
  local cbt = S.turn and S.turn.cbt
  if not cbt then return { error = "not your turn" } end
  if cbt.actionUsed then return { error = "action used" } end
  if kind == "dash" then
    cbt.movementLeft = cbt.movementLeft + cbt.speed * C.UNITS_PER_FOOT
    cbt.actionUsed = true
    DND.logf("%s dashes (+" .. cbt.speed .. " ft).", cbt.name)
  elseif kind == "disengage" then
    cbt.flags.disengaged = true
    cbt.actionUsed = true
    DND.logf("%s disengages — movement will not provoke.", cbt.name)
  elseif kind == "dodge" then
    cbt.flags.dodge = true
    cbt.actionUsed = true
    DND.logf("%s takes the Dodge action (attacks vs it have disadvantage).", cbt.name)
  elseif kind == "help" then
    cbt.actionUsed = true
    DND.logf("%s helps an ally's next check.", cbt.name)
  elseif kind == "hide" then
    cbt.actionUsed = true
    Resolve.stealth(cbt, cbt.flags.hideDc or 12)
  elseif kind == "ready" then
    cbt.actionUsed = true
    cbt.flags.readied = { attack = opts and opts.attack or Combatant.primaryAttack(cbt) }
    DND.logf("%s readies %s.", cbt.name, cbt.flags.readied.attack.name)
  elseif kind == "heal" then
    if cbt.hitDice <= 0 then return { error = "no Hit Dice left" } end
    cbt.actionUsed = true
    Resolve.spendHitDie(cbt)
  elseif kind == "stabilize" then
    local down = Combat.downedFoeOrAlly(cbt)
    if not down then return { error = "nobody to stabilise" } end
    cbt.actionUsed = true
    Resolve.stabilize(cbt, down)
  else
    return { error = "unknown action: " .. tostring(kind) }
  end
  DND.ui.showActions(cbt)
  return { ok = true }
end

--- Bonus actions: off-hand attack, class features, second wind.
function Combat.useBonus(kind)
  local cbt = S.turn and S.turn.cbt
  if not cbt then return { error = "not your turn" } end
  -- The flag goes up only once the attack is committed. Setting it first and
  -- unwinding it on every early return is how you get "two bonus actions" or
  -- "none at all", depending on which branch forgets to put it back.
  if cbt.bonusUsed then return { error = "bonus action used" } end
  if kind == "offhand" then
    local a = cbt.bonusAttack
    if not a then return { error = "no light weapon to off-hand" } end
    local tgt = S.cycleTarget or (Combat.enemiesOf(cbt)[1])
    if not tgt then return { error = "no target in reach" } end
    local p = Resolve.attack(cbt, tgt, a, { force = true })
    if p.error then return p end
    cbt.bonusUsed = true
    S.pending = p
    return Combat.resolvePending()
  elseif kind == "secondwind" then
    cbt.bonusUsed = true
    local r = Resolve.spendHitDie(cbt)
    DND.logf("%s uses Second Wind.", cbt.name)
    return r
  end
  for _, t in ipairs(cbt.traits) do
    if t.key == kind then
      cbt.bonusUsed = true
      if t.onUse then return t.onUse(cbt) or { ok = true } end
      return { ok = true }
    end
  end
  return { error = "no such bonus: " .. tostring(kind) }
end

function Combat.downedFoeOrAlly(cbt)
  local pool = (cbt.side == C.SIDE.PARTY) and Combatant.living(C.SIDE.PARTY)
             or Combatant.living(C.SIDE.FOES)
  for _, other in ipairs(pool) do
    if other.hp <= 0 and other.downed then return other end
  end
  for _, other in ipairs(Combatant.all()) do
    if other.hp <= 0 and other.downed and other.side == cbt.side then return other end
  end
  return nil
end

--- If the active creature has nothing left to do, close its turn promptly.
--- Convenience only: closing the turn when nothing is left to do. It has to be
--- switchable, because in tests every deferred callback runs synchronously and
--- a turn that evaporates mid-assertion looks exactly like a rules bug.
function Combat.maybeAutoEnd(cbt)
  if not DND.config.autoEndTurn then return end
  if not cbt or not S.running then return end
  if S.turn and S.turn.cbt ~= cbt then return end
  if cbt.side ~= C.SIDE.PARTY then return end
  if cbt.flags.inAction then return end   -- the Action is still resolving its swings
  if cbt.actionUsed and cbt.bonusUsed and (cbt.movementLeft < C.FIVE_FEET) then
    DND.ui.setHint("Nothing left to do — turn ends.")
    w3.after(DND.testMode and 0 or 0.8, function()
      if S.turn and S.turn.cbt == cbt and not S.armed and not S.pending then
        Combat.endTurn(cbt)
      end
    end)
  end
end

---------------------------------------------------------------------- DM tools
--- Put a named creature in the driver's seat without advancing anybody else.
--- A party turn is *waited for*, so an endTurn() loop to reach it would also
--- run straight through the AI's turn and land back where it started; this is
--- the primitive both the DM console and the test suite need.
function Combat.giveTurn(name)
  local t = DND.Combat.turns
  if #t.order == 0 then
    DND.logf("giveTurn: no combat is running")
    return nil
  end
  local needle = name and name:lower() or nil
  for i, e in ipairs(t.order) do
    if (not needle) or e.cbt.name:lower() == needle then
      t.index = i
      S.turn, S.armed, S.pending, S.reactionPrompt = e, nil, nil, nil
      Combat.beginTurn(e.cbt)
      return e.cbt
    end
  end
  return nil
end

function Combat.rerollLast()
  if not S.pending then return { error = "no attack in flight" } end
  local p = S.pending
  local fresh = Dice.attackRoll(p.action.toHit or 0, p.ac, { adv = p.adv })
  DND.logf("DM forces a reroll: %d → %d", p.roll.total, fresh.total)
  p.roll = fresh
  p.hit = fresh.hit
  p.damage = 0
  if fresh.hit then
    local r = Dice.rollExpr(p.action.damage, { double = fresh.crit,
      bonus = p.action.finesse and math.max(p.attacker.mods.str, p.attacker.mods.dex)
             or (p.action.ability and p.attacker.mods[p.action.ability] or p.attacker.mods.str) })
    p.damage = r.total
  end
  return { ok = true }
end

function Combat.setHp(cbt, v)
  cbt.hp = C.clamp(v, 0, cbt.hpMax)
  if cbt.hp > 0 then cbt.downed = false end
  Combatant.sync(cbt)
  DND.logf("DM sets %s to %d hp.", cbt.name, cbt.hp)
end

function Combat.grantAdvantage(cbt)
  cbt.flags.hidden = true
  DND.logf("%s is treated as unseen until it acts.", cbt.name)
end

return Combat

end

-- ------------------------------------------------------------ dnd_ui.lua
do
--[[ =========================================================================
  dnd_ui.lua — everything the player can see.

  WC3 gives us a command card we cannot write to at runtime and a tooltip we
  cannot reformat on the fly, so the D&D layer builds its own chrome out of
  raw frames (BlzCreateFrameByType on stock templates = no FDF, no .toc, works
  in any patch) plus floating text tags. If a frame native is unavailable the
  panel silently degrades to the native log and hotkeys — the game is playable
  with the UI switch off, which is worth a lot when you are debugging at 1am.
========================================================================== ]]
DND = DND or {}
DND.ui = {}
local ui = DND.ui
local C = DND.CONST
local w3 = DND.w3

ui.enabled = true
ui.frames = {}
ui.state = { hint = "", log = {}, tracker = {}, actions = {}, targets = {} }
local L = ui.state

---------------------------------------------------------------------- frames
local function mk(typ, name, parent, inherits)
  if DND.testMode or not ui.enabled then return nil end
  if not w3.has("BlzCreateFrameByType") then return nil end
  local f = BlzCreateFrameByType(typ, name, parent or BlzGetOriginFrame(ORIGIN_FRAME_GAME_UI, 0),
                                 inherits or "", 0)
  return f
end

local function txt(name, x, y, size, w, h)
  local f = mk("TEXT", name, nil, "TooltipTextTemplate")
  if not f then return nil end
  BlzFrameSetAbsPoint(f, FRAMEPOINT_TOPLEFT, x, y)
  BlzFrameSetSize(f, w or 0.30, h or 0.026)
  BlzFrameSetText(f, "")
  return f
end

local function button(name, label, x, y, w, h, onClick, key)
  local f = mk("BUTTON", name, nil, "StandardButtonTemplate")
  if not f then return nil end
  BlzFrameSetAbsPoint(f, FRAMEPOINT_CENTER, x, y)
  BlzFrameSetSize(f, w or 0.072, h or 0.036)
  local t = BlzCreateFrameByType("TEXT", name .. "Label", f, "TooltipTextTemplate", 0)
  BlzFrameSetAllPoints(t, f)
  BlzFrameSetText(t, (key and ("[" .. key .. "] " .. label)) or label)
  local tr = CreateTrigger()
  BlzTriggerRegisterFrameEvent(tr, f, FRAMEEVENT_CONTROL_CLICK)
  TriggerAddAction(tr, function()
    -- buttons steal keyboard focus; bounce it so hotkeys keep working
    BlzFrameSetEnable(f, false); BlzFrameSetEnable(f, true)
    if onClick then onClick() end
  end)
  return f
end

function ui.init()
  if DND.testMode then return end
  ui.state.round   = txt("DNDTitle", 0.005, 0.005, 10)
  ui.state.log0    = txt("DNDLog0", 0.005, 0.036, 9)
  ui.state.log1    = txt("DNDLog1", 0.005, 0.060, 9)
  ui.state.log2    = txt("DNDLog2", 0.005, 0.084, 9)
  ui.state.hintBox = txt("DNDHint", 0.005, 0.108, 9)
  ui.state.tracker = txt("DNDTracker", 0.80, 0.02, 9)
  ui.state.status  = txt("DNDStatus", 0.34, 0.02, 11)
  ui.enabled = ui.state.round ~= nil
end

---------------------------------------------------------------------- log
function ui.pushLog(line)
  local log = L.log
  log[#log + 1] = line
  while #log > 60 do table.remove(log, 1) end
  if not ui.enabled then return end
  local recent = {}
  for i = math.max(1, #log - 2), #log do recent[#recent + 1] = log[i] end
  if ui.state.log0 then BlzFrameSetText(ui.state.log0, recent[1] or "") end
  BlzFrameSetText(ui.state.log1, recent[1] or "")
  if ui.state.log1 then BlzFrameSetText(ui.state.log1, recent[2] or "") end
  if ui.state.log2 then BlzFrameSetText(ui.state.log2, recent[3] or "") end
end

function ui.setHint(s)
  L.hint = s
  if ui.enabled and ui.state.hintBox then BlzFrameSetText(ui.state.hintBox, s) end
end

---------------------------------------------------------------------- tracker
function ui.buildTracker()
  L.tracker = DND.Turns.summary(DND.Combat.turns)
  if not ui.enabled or not ui.state.tracker then return end
  local lines = { "|cffffe066INITIATIVE|r" }
  for i, s in ipairs(L.tracker) do lines[#lines + 1] = s end
  BlzFrameSetText(ui.state.tracker, table.concat(lines, "\n"))
end

function ui.refreshStatus(cbt)
  if not ui.enabled or not ui.state.status then return end
  local con = {}
  for k in pairs(cbt.statuses) do con[#con + 1] = k end
  table.sort(con)
  local s = cbt.name .. ": " .. cbt.hp .. "/" .. cbt.hpMax .. " hp, AC " .. cbt.ac
  if #con > 0 then s = s .. "  |cffff8866[" .. table.concat(con, ", ") .. "]|r" end
  BlzFrameSetText(ui.state.status, s)
end

---------------------------------------------------------------------- action bar
local function clearTable(t) for k in pairs(t) do t[k] = nil end end

function ui.showActions(cbt)
  clearTable(L.actions)
  for i, a in ipairs(cbt.actions) do
    L.actions[#L.actions + 1] = {
      key = tostring(i), kind = "attack", index = i,
      label = a.name .. (DND.Combatant.extraAttacks(cbt) > 1 and " x2" or ""),
      sub = a.toHit and (C.signed(a.toHit) .. " to hit, " .. a.damage) or ("DC " .. a.spellDc),
      enabled = (not cbt.actionUsed) or a.bonus == true,
    }
  end
  for i, sp in ipairs(cbt.spells) do
    local left = sp.level == 0 and 99 or (cbt.slots[sp.level] or 0)
    L.actions[#L.actions + 1] = {
      key = string.format("F%d", i), label = sp.name, kind = "spell", index = i,
      sub = (sp.level == 0 and "cantrip" or (C.ordinal(sp.level) .. " " .. left .. "/" .. (cbt.slotMax[sp.level] or 0))),
      enabled = (left > 0) and (not cbt.actionUsed or sp.bonus == true),
    }
  end
  L.actions[#L.actions + 1] = { key = "Q", label = "Dash", kind = "act", act = "dash",
                                enabled = not cbt.actionUsed }
  L.actions[#L.actions + 1] = { key = "W", label = "Disengage", kind = "act", act = "disengage",
                                enabled = not cbt.actionUsed }
  L.actions[#L.actions + 1] = { key = "E", label = "Dodge", kind = "act", act = "dodge",
                                enabled = not cbt.actionUsed }
  L.actions[#L.actions + 1] = { key = "R", label = "Hide", kind = "act", act = "hide",
                                enabled = not cbt.actionUsed }
  L.actions[#L.actions + 1] = { key = "T", label = "Hit Die", kind = "act", act = "heal",
                                enabled = cbt.hitDice > 0 and not cbt.actionUsed }
  L.actions[#L.actions + 1] = { key = "Y", label = "Stabilise", kind = "act", act = "stabilize",
                                enabled = DND.Combat.downedFoeOrAlly(cbt) ~= nil }
  -- keep the bar honest: a listed key that the input layer does not read is a
  -- lie the player will discover the hard way
  L.actions.checked = true
  for i, t in ipairs(cbt.traits) do
    L.actions[#L.actions + 1] = { key = string.format("F%d", #cbt.spells + i), label = t.name,
                                  kind = "bonus", trait = t.key,
                                  sub = t.desc or "bonus action",
                                  enabled = not cbt.bonusUsed }
  end
  if cbt.bonusAttack then
    L.actions[#L.actions + 1] = { key = "G", label = "Off-hand", kind = "bonus",
                                  sub = cbt.bonusAttack.damage,
                                  enabled = not cbt.bonusUsed }
  end
  L.actions[#L.actions + 1] = { key = "SPACE", label = "End Turn", kind = "end", enabled = true }
  L.targets = ui.targetList(cbt)
  ui.renderActionBar()
end

--- Enemies currently in reach for whatever is armed — this is what makes the
--- 1-9 keys feel like a tactics game rather than a menu.
function ui.targetList(cbt, armed)
  local out = {}
  for _, foe in ipairs(DND.Combat.enemiesOf(cbt)) do
    local a = armed and (armed.action or armed.spell) or cbt.actions[1]
    local need = (a and a.range and C.ft(a.range)) or (a and a.reach) or C.ft(5)
    local d = w3.dist(cbt.unit, foe.unit)
    out[#out + 1] = { cbt = foe, inRange = d <= need + C.FIVE_FEET,
                      dist = C.round(C.unitsToFeet(d)), hp = foe.hp, ac = foe.ac }
  end
  return out
end

function ui.renderActionBar()
  L.actionText = {}
  for i, a in ipairs(L.actions) do
    L.actionText[i] = string.format("%s%s [%s] %s — %s",
      a.enabled and " " or "x", "", a.key, a.label, a.sub or "")
  end
  L.targetText = {}
  for i, t in ipairs(L.targets) do
    L.targetText[i] = string.format("%d. %s%s  AC%d  %dhp  %dft", i, t.cbt.name,
      t.inRange and " (in range)" or "  ", t.ac, t.hp, t.dist)
  end
  if not ui.enabled then return end
  local parts = { "|cffffe066ACTIONS|r" }
  for i = 1, #L.actionText do parts[#parts + 1] = L.actionText[i] end
  parts[#parts + 1] = "|cffffe066TARGETS|r"
  for i = 1, math.min(8, #L.targetText) do parts[#parts + 1] = L.targetText[i] end
  if ui.enabled and ui.state.round then BlzFrameSetText(ui.state.round, table.concat(parts, "\n")) end
end

function ui.updateMovement(cbt)
  L.moveText = string.format("%s: %.0f/%.0f ft left, action %s, bonus %s, reaction %s",
    cbt.name, C.round(C.unitsToFeet(cbt.movementLeft)), cbt.speed,
    cbt.actionUsed and "used" or "ready", cbt.bonusUsed and "used" or "ready",
    cbt.reactionTaken and "used" or "ready")
  if ui.enabled then ui.setHint(L.moveText) end
end

function ui.hideActions(cbt)
  clearTable(L.actions); clearTable(L.targets)
  if ui.enabled and ui.state.round then BlzFrameSetText(ui.state.round, "") end
end

function ui.setActive(cbt)
  L.active = cbt.cid
  ui.refreshStatus(cbt)
  ui.updateMovement(cbt)
  if DND.testMode then return end
  if cbt.unit and not DND.testMode then
    w3.safe("SelectUnitForSingleUser", cbt.unit)
  end
end
function ui.clearActive() L.active = nil end

---------------------------------------------------------------------- prompts
function ui.promptPlayer(cbt)
  ui.setHint(string.format("YOUR TURN: pick an action (1-%d), move with A/S/D/W, "
    .. "Space ends.", math.max(9, #cbt.actions)))
end

--- Three different pending shapes reach this prompt (a swing in flight, an
--- opportunity attack, a readied action) and they do not all carry the same
--- fields, so every one of them is defaulted. %d against a nil ac is a crash in
--- the single most player-visible moment in the game.
function ui.promptReaction(cbt, options, pending)
  local names = {}
  for i, o in ipairs(options) do names[i] = string.format("%d) %s", i, o.label or "?") end
  local who = pending and pending.attacker and pending.attacker.name or "the attacker"
  local ac = (pending and pending.ac) or (pending and pending.roll and pending.roll.ac) or 0
  local what = (pending and pending.action and pending.action.name) or "attack"
  ui.setHint(string.format("|cffff8866REACTION — %s|r: %s's %s is in the air vs AC %d."
    .. "  %s  (Y=take, N=hold)",
    cbt and cbt.name or "?", who, what, ac, table.concat(names, "  ")))
end

function ui.clearReaction() ui.setHint("Reaction resolved.") end

function ui.showTargeting(cbt, a)
  L.armed = a
  ui.setHint(string.format("Armed: %s. Pick a target with 1-9, or Esc to cancel.",
    a.name or (a and a.desc) or "?"))
end
function ui.clearTargeting() L.armed = nil end

---------------------------------------------------------------------- feedback
-- The dice have to be *seen*. This is the single biggest "it's D&D now" win.
function ui.showHit(attacker, target, roll, dealt, pending)
  if not target.unit then return end
  w3.textTag(target.unit, tostring(dealt) .. (roll.crit and "!!" or ""), 12,
    roll.crit and 255 or 255, roll.crit and 230 or 120, 60)
  if roll.crit then w3.textTag(target.unit, "CRIT", 10, 255, 215, 0) end
  local art = (pending and pending.type and C.DMG_EFFECT[pending.type])
    or "Abilities\\Weapons\\Axe\\AxeMissile\\AxeMissile.mdl"
  w3.fxTarget(art, target.unit, "origin")
end

function ui.showMiss(attacker, target, roll, ac)
  if not target.unit then return end
  w3.textTag(target.unit, "MISS", 11, 200, 200, 200)
  if ac and roll then
    w3.textTag(attacker.unit, roll.natural .. C.signed(roll.mod) .. " vs " .. ac, 8,
      180, 180, 255)
  end
end

function ui.showSave(target, r)
  if not target.unit then return end
  w3.textTag(target.unit, r.success and "SAVE ok" or "SAVE fail", 10,
    r.success and 140 or 255, r.success and 255 or 90, 140)
end

function ui.showHeal(target, got)
  if not target.unit then return end
  w3.textTag(target.unit, "+" .. got, 11, 120, 255, 120)
end

function ui.showSpellHit(caster, target, spell, dmg)
  if target and target.unit then
    w3.fxTarget(C.SCHOOL_ICON[spell.school or "evocation"], target.unit, "origin")
  end
end

function ui.showDowned(cbt)
  ui.setHint("|cffff8866" .. cbt.name .. " is down.|r  Death saves begin.")
  if cbt.unit then w3.textTag(cbt.unit, "DOWN", 12, 255, 60, 60) end
end

function ui.showDied(cbt)
  if cbt.unit then w3.textTag(cbt.unit, "x", 14, 255, 40, 40) end
  ui.buildTracker()
end

function ui.pulse(cbt)
  if cbt.unit then w3.playAnim(cbt.unit, "spell") end
end

function ui.clear()
  clearTable(L.actions); clearTable(L.targets); L.hint = ""
  if ui.enabled and ui.state.round then BlzFrameSetText(ui.state.round, "") end
  if ui.enabled and ui.state.tracker then BlzFrameSetText(ui.state.tracker, "") end
end

--- A compact text dump of the panel — the harness asserts against this, so the
--- UI is not just decoration, it is checked code.
function ui.dump()
  local out = { string.format("ROUND %d  PHASE %s", DND.Combat.turns.round,
    DND.Combat.state.phase) }
  for i = 1, #L.actionText or 0 do out[#out + 1] = L.actionText[i] end
  for i = 1, #L.targetText or 0 do out[#out + 1] = L.targetText[i] end
  out[#out + 1] = L.hint
  return table.concat(out, "\n")
end

return ui

end

-- ------------------------------------------------------------ dnd_ai.lua
do
--[[ =========================================================================
  dnd_ai.lua — enemies that play by exactly the rules you do.

  There is no privileged AI damage path: the AI calls the same
  Combat.move / Combat.executeOn entry points your keypresses call. That is the
  only reason this stays maintainable — every rule is written once, and the AI
  cannot cheat in a way the player never can.

  Scoring is deliberately simple:
      can I kill it?  >  can I hit it?  >  can I reach it?  >  do I look smart?
========================================================================== ]]
DND = DND or {}
DND.ai = {}
local AI = DND.ai
local C = DND.CONST
local w3 = DND.w3
local Dice = DND.Dice
local Resolve = DND.Resolve
local Combatant = DND.Combatant

AI.thinkDelay = 0.45        -- a beat between decisions so turns read as turns
AI.maxActions = 24          -- hard stop: a bad eval can never hang the game
AI.samples = 16             -- rays per approach cone (see candidates)
local actionsTaken = 0

local function uiPulse(cbt)
  if DND.ui and DND.ui.pulse then DND.ui.pulse(cbt) end
end

---------------------------------------------------------------------- maths
--- P(roll + bonus >= ac), with the advantage/disadvantage adjustment. Kept as
--- closed form because the AI evaluates hundreds of these per turn.
local function hitChance(bonus, ac, adv)
  local need = ac - bonus
  local faces = 21 - C.clamp(need, 2, 21)     -- natural 1 always misses
  if need <= 2 then faces = 19 end            -- everything but a 1 hits
  local p = faces / 20
  if adv >= 1 then p = 1 - (1 - p) * (1 - p) end
  if adv <= -1 then p = p * p end
  return C.clamp(p, 0.05, 0.95)
end

local function avgDamage(cbt, action, crit)
  local t = C.parseDice(action.damage)
  if not t then return 0 end
  local dmod = action.dmod
  if dmod == nil then
    dmod = action.ability and cbt.mods[action.ability] or cbt.mods.str
    if action.finesse then dmod = math.max(cbt.mods.str, cbt.mods.dex) end
  end
  local avg = dmod or 0                        -- 5e doubles the DICE, never the mod
  for _, d in ipairs(t.dice) do
    avg = avg + (crit and d.d or (d.d + 1) / 2)
  end
  for _, ex in ipairs(action.extraDice or {}) do
    local et = C.parseDice(ex.expr)
    if et then
      for _, d in ipairs(et.dice) do
        avg = avg + (crit and d.d or (d.d + 1) / 2)
      end
    end
  end
  return math.max(1, avg)
end

--- What standing in the open at (x, y) will cost us in free swings.
local function threatCost(cbt, x, y)
  local cost = 0
  for _, other in ipairs(DND.Combat.enemiesOf(cbt)) do
    local oa = Combatant.primaryAttack(other)
    if oa and not oa.range then
      local d = w3.distPts(x, y, GetUnitX(other.unit), GetUnitY(other.unit))
      if d <= (oa.reach or C.ft(5)) + C.FIVE_FEET then
        cost = cost + avgDamage(other, oa, false)
             * hitChance(oa.toHit or 0, Combatant.ac(cbt), 0) * 0.5
      end
    end
  end
  return cost
end

local function canSee(cbt, foe)
  if foe.flags.hidden and w3.dist(cbt.unit, foe.unit) > C.ft(10) then return false end
  return true
end

local function index(cbt, action)
  for i, a in ipairs(cbt.actions) do
    if a == action then return i end
  end
  return 1
end

---------------------------------------------------------------------- eval
--- How much is this swing worth? Expected damage, with a huge bonus for kills.
function AI.scoreAttack(cbt, foe, action)
  if not canSee(cbt, foe) then return -100 end
  if action.recharge and not action.ready then return -1 end
  local cover = Resolve.coverBonus(cbt, foe)
  local ac = Combatant.ac(foe, { cover = cover, melee = not action.range })
  local adv = Resolve.situationalAdv(cbt, foe, action)
  local chance = hitChance(action.toHit or (Combatant.spellAttack(cbt)), ac, adv)
  local avg = avgDamage(cbt, action, false)
  if action.save then avg = avg * (1 - hitChance(0, action.dc or 13, adv) * 0.5) end
  -- One Attack action may be several swings (Extra Attack).  Expected damage is the
  -- sum, and the finisher test uses the sum too, because two half-kills are a kill.
  local swings = Combatant.extraAttacks(cbt)
  local s = chance * avg * 1.6 * swings
  if avg * swings >= foe.hp then s = s + 400 end
  if foe.hp <= foe.hpMax * 0.3 and chance > 0.4 then s = s + 90 end
  if action.aoe then s = s + 25 end
  if not action.range and w3.dist(cbt.unit, foe.unit) > (action.reach or C.ft(5)) then
    s = s - threatCost(cbt, GetUnitX(cbt.unit), GetUnitY(cbt.unit))
  end
  return s
end

--- Candidate standing spots. WC3 exposes no pathfinder query, so we fan out
--- from the creature toward the target and, once adjacent, around the target's
--- reach ring. Sampled on the 5 ft grid so it lands where the player can see.
function AI.candidates(cbt, foe, reach, budget)
  local out = {}
  local ux, uy = GetUnitX(cbt.unit), GetUnitY(cbt.unit)
  local tx, ty = GetUnitX(foe.unit), GetUnitY(foe.unit)
  local d = w3.distPts(ux, uy, tx, ty)
  -- 1) approach: walk toward the target along a fan of rays, stopping at the
  --    budget AND at the target's reach. Forgetting either cap is how the AI
  --    ends up scoring "stand still" as its best option in an empty field.
  local step = C.ft(5)
  local n = C.clamp(math.floor(budget / step), 1, 12)
  local reach = C.clamp(reach, C.ft(5), C.ft(30))
  local base = math.atan2(ty - uy, tx - ux)
  local rays = AI.samples
  for i = 0, rays - 1 do
    local a = base + (i / (rays - 1) - 0.5) * math.pi * 0.85
    for k = 1, n do
      local x, y = ux + math.cos(a) * step * k, uy + math.sin(a) * step * k
      local stop = w3.distPts(x, y, tx, ty)
      local walked = w3.distPts(ux, uy, x, y)
      if walked > budget + C.FIVE_FEET then break end  -- out of movement, stop this ray
      if stop < reach - C.ft(2.5) then break end       -- already inside reach
      out[#out + 1] = { x = x, y = y, bias = -k, closesIn = stop < d,
                        walked = walked,
                        adjacent = stop <= reach + C.FIVE_FEET }
    end
  end
  -- 2) the reach ring, for encircling / flanking once you are close enough
  for i = 0, 7 do
    local a = i * math.pi / 4
    for _, pad in ipairs({ -C.FIVE_FEET, 0, C.FIVE_FEET * 2 }) do
      local r = reach - C.ft(5) + pad
      if r < C.ft(5) then r = C.ft(5) end
      local x, y = tx + math.cos(a) * r, ty + math.sin(a) * r
      if w3.distPts(ux, uy, x, y) <= budget + C.FIVE_FEET then
        out[#out + 1] = { x = x, y = y, bias = 6, ring = true }
      end
    end
  end
  -- 3) hold position (attack without moving / stay at range / keep cover)
  out[#out + 1] = { x = ux, y = uy, bias = 1 }
  return out
end

--- Best spot to stand for the primary attack, scored by reach minus exposure.
function AI.bestStep(cbt, foe)
  local a = Combatant.primaryAttack(cbt)
  local reach = a and (a.reach or C.ft(5)) or C.ft(5)
  local budget = cbt.movementLeft or (cbt.speed * C.UNITS_PER_FOOT)
  if cbt.flags.wantDash then budget = budget + cbt.speed * C.UNITS_PER_FOOT end
  local best
  for _, pos in ipairs(AI.candidates(cbt, foe, reach, budget)) do
    if pos.x and pos.y then
      local s = pos.bias or 0
      local d = w3.distPts(pos.x, pos.y, GetUnitX(foe.unit), GetUnitY(foe.unit))
      if d <= reach + C.FIVE_FEET then s = s + 30 end
      if pos.adjacent then s = s + 14 end
      if not cbt.flags.disengaged then
        s = s - threatCost(cbt, pos.x, pos.y)
      end
      -- never pay to shuffle sideways
      s = s - (pos.walked or 0) * 0.004
      if pos.ring then s = s + 4 end
      if not best or s > best.score then
        best = { score = s, x = pos.x, y = pos.y, foe = foe, action = a }
      end
    end
  end
  return best
end

---------------------------------------------------------------------- turn
function AI.takeTurn(cbt, done)
  actionsTaken = 0
  local guard = 0
  while actionsTaken < AI.maxActions do
    guard = guard + 1
    if guard > AI.maxActions + 4 then break end
    if not AI.step(cbt) then break end
  end
  -- breath weapons: "Recharge 5-6"
  for _, a in ipairs(cbt.actions) do
    if a.recharge and not a.ready then
      if Dice.roll(1, 6) >= 5 then
        a.ready = true
        DND.logf("%s's %s recharges.", cbt.name, a.name)
      end
    end
  end
  if DND.config.deathSaves and cbt.downed then Resolve.deathSave(cbt) end
  -- The caller usually wants the turn closed when we finish. A test (or a DM
  -- reviewing what the AI did) needs it held open, so that is opt-out rather
  -- than something the caller has to work around.
  if done and DND.config.aiAutoEnd ~= false then done() end
end

--- One decision. Returns true when something was spent, false to end the turn.
function AI.step(cbt)
  if actionsTaken >= AI.maxActions then return false end
  if cbt.hp <= 0 or cbt.removed then return false end
  actionsTaken = actionsTaken + 1

  local foes = DND.Combat.enemiesOf(cbt)
  if #foes == 0 then return false end

  -- 1) swing at anything already in reach
  if not cbt.actionUsed then
    local best
    for _, foe in ipairs(foes) do
      for _, a in ipairs(cbt.actions) do
        local need = a.reach or (a.range and C.ft(a.range)) or C.ft(5)
        if w3.dist(cbt.unit, foe.unit) <= need + C.FIVE_FEET then
          local s = AI.scoreAttack(cbt, foe, a)
          if not best or s > best.score then best = { score = s, foe = foe, action = a } end
        elseif not best then
          -- Out of reach: keep it as a fallback so the creature at least SWINGS
          -- and the rules refuse it. Skipping silently is how a fight stalls
          -- into a 400-round stalemate with nobody doing anything.
          best = { score = -60, foe = foe, action = a, desperate = true }
        end
      end
      -- spells are just attacks with different maths
      for i, sp in ipairs(cbt.spells or {}) do
        local wantsFoe = sp.needTarget or sp.attackRoll or sp.save
        local lvl = sp.level or 0
        -- Cantrips have no slot to spend, so they need to be considered on the
        -- same footing as slotted spells; a wizard who never throws a firebolt
        -- is a wizard who stalemates the fight.
        if lvl == 0 or (lvl > 0 and (cbt.slots[lvl] or 0) > 0 and not sp.bonus) then
          local s = AI.scoreAttack(cbt, foe, {
            toHit = sp.attackRoll and Combatant.spellAttack(cbt) or nil,
            damage = sp.damage, save = sp.save,
            reach = C.ft(sp.range or 60), range = sp.range, aoe = sp.aoe })
          local wantsFoe = sp.needTarget or sp.attackRoll
          local inRange = w3.dist(cbt.unit, foe.unit) <= C.ft(sp.range or 5) + C.FIVE_FEET
          local usable = (sp.level or 0) == 0 or (cbt.slots[sp.level] or 0) > 0
          if usable and (not wantsFoe or (inRange and not sp.needTarget))
             and (not wantsFoe or sp.needTarget) and inRange
             and s > 8 and (not best or s > best.score) then
            best = { score = s, foe = wantsFoe and foe or nil, spell = sp, index = i }
          end
        end
      end
    end
    if best and best.score > -50 then
      if best.spell then
        local arm = DND.Combat.armAction("spell", best.index)
        if arm and not arm.error then
          local r = DND.Combat.executeOn(best.foe)
          if r and not r.error then return true end
          if r and r.error then DND.logf("AI: %s could not cast (%s)", cbt.name, r.error) end
          DND.Combat.cancelAction()
        elseif arm and arm.error then
          DND.logf("AI: %s could not arm spell (%s)", cbt.name, arm.error)
        end
      else
        local arm = DND.Combat.armAction("attack", index(cbt, best.action),
          best.desperate and { force = true } or nil)
        if arm and not arm.error then
          local r = DND.Combat.executeOn(best.foe)
          if r and not r.error then
            if best.action.recharge then best.action.ready = false end
            return true
          end
          if r and r.error then DND.logf("AI: %s could not attack (%s)", cbt.name, r.error) end
          DND.Combat.cancelAction()
        elseif arm and arm.error then
          DND.logf("AI: %s could not arm attack (%s)", cbt.name, arm.error)
        end
      end
    end
  end

  -- 3b) still nothing? swing anyway. The rules will refuse it if the target is
  -- out of reach, and that refusal is far better than a silent stalemate.
  if not cbt.actionUsed then
    local foe = foes[1]
    local idx = index(cbt, Combatant.primaryAttack(cbt))
    local arm = DND.Combat.armAction("attack", idx, { force = true })
    if arm and not arm.error then
      local r = DND.Combat.executeOn(foe)
      if r and not r.error then return true end
      DND.Combat.cancelAction()
    end
  end

  -- 4) bonus actions: Nimble Escape, Aggressive, Martial Advantage, off-hand
  if not cbt.bonusUsed then
    for _, t in ipairs(cbt.traits or {}) do
      if t.bonus and t.onUse then
        t.onUse(cbt)
        cbt.bonusUsed = true
        return true
      end
    end
    if cbt.bonusAttack and not cbt.flags.bonusAttackUsed then
      local foe = foes[1]
      cbt.flags.bonusAttackUsed = true
      cbt.bonusUsed = true
      local p = Resolve.attack(cbt, foe, cbt.bonusAttack, { force = true })
      if p and not p.error then
        p.reactionWindow = nil
        Resolve.commit(p)
        return true
      end
    end
  end

  -- 2) nothing in reach: spend the move getting into it
  if cbt.movementLeft and cbt.movementLeft > C.FIVE_FEET then
    local plan
    for _, foe in ipairs(foes) do
      local p = AI.bestStep(cbt, foe)
      if p and (not plan or p.score > plan.score) then plan = p end
    end
    if (not plan or plan.score <= 1) and cbt.actionUsed == false then
      -- nothing in reach and no good square: straight-line approach. 5e calls
      -- this "move toward your objective"; WC3's pathing handles the terrain.
      local pf = foes[1]
      local ux, uy = GetUnitX(cbt.unit), GetUnitY(cbt.unit)
      local tx, ty = GetUnitX(pf.unit), GetUnitY(pf.unit)
      local dd = w3.distPts(ux, uy, tx, ty)
      if dd > C.FIVE_FEET then
        -- walk until either the budget runs out or we are 5 ft from the target
        local step = math.min(cbt.movementLeft, math.max(0, dd - C.FIVE_FEET))
        if step > C.FIVE_FEET then
          local t = step / dd
          plan = { score = 20, x = ux + (tx - ux) * t, y = uy + (ty - uy) * t, foe = pf }
          cbt.flags.closing = true
        end
      end
    end
    if plan and plan.x then
      local mv = DND.Combat.move({ x = plan.x, y = plan.y },
        plan.score < 20 and { dash = cbt.flags.wantDash } or nil)
      cbt.flags.wantDash = nil
      if mv and not mv.error then
        uiPulse(cbt)
        if cbt.flags.closing then
          cbt.flags.closing = nil
          cbt.actionUsed = true     -- walking the whole field is the turn's work
        end
        return true
      end
      if mv and mv.error then
        DND.logf("AI: %s is stuck (%s)", cbt.name, mv.error)
      end
    end
  end

  -- 3) support magic: heal or buff the friend who needs it most
  if not cbt.actionUsed then
    for _, ally in ipairs(Combatant.living(cbt.side)) do
      if ally ~= cbt and ally.hp < ally.hpMax * 0.45 then
        for i, sp in ipairs(cbt.spells or {}) do
        local wantsFoe = sp.needTarget or sp.attackRoll or sp.save
          if (sp.heal or (sp.selfEffect and ally ~= cbt)) and not sp.attackRoll
             and (sp.level or 0) > 0 and (cbt.slots[sp.level] or 0) > 0 then
            local need = C.ft(sp.range or 5)
            if w3.dist(cbt.unit, ally.unit) <= need + C.FIVE_FEET then
              local arm = DND.Combat.armAction("spell", i)
              if arm and not arm.error then
                local r = DND.Combat.executeOn(ally)
                if r and not r.error then return true end
                DND.Combat.cancelAction()
              end
            end
          end
        end
      end
    end
  end

  return false
end

--- Called from Combat.beginTurn for the AI side.
return AI

end

