        local foe = DND.Combat.enemiesOf(c)[1]
        if not foe then return { error = "nothing to charge" } end
        local u = c.unit
        local fx, fy = GetUnitX(u), GetUnitY(u)
        local tx, ty = GetUnitX(foe.unit), GetUnitY(foe.unit)
